// Cyrus wiring phase 2: the ENQUEUE side of delivery (pure, no I/O, no Nxeon import). What a portal request becomes:
//   - the job payload (a `cyrusDelivery` discriminator on the existing GAME_MOD_SYNC job type, v:1), validated both
//     when it is written (portal) and when it is read (worker);
//   - an idempotency key (a client key scoped to the account, or one derived from the request itself);
//   - the parts of a build that WOULD be delivered with the current switches (and why each other part is left out),
//     plus the acknowledgements the customer must give (restart, world generation);
//   - the STATUS READ MODEL for the portal: one job row -> a customer-safe state (queued, running, delivered, updated,
//     uninstalled, unchanged, pending_restart, refused, rolled_back, rollback_incomplete, failed) with the steps, the
//     rollback report and the health verdict as the worker stored them. Failure and rollback are never softened.
import { createHash } from "node:crypto";
import { switches } from "./plan";
import type { DeliveryOutcome, DeliveryResult, Env } from "./types";

export const DELIVERY_PAYLOAD_VERSION = 1 as const;
export const DELIVERY_OPS = ["deliver", "uninstall", "modpack_install", "modpack_uninstall"] as const;
export type DeliveryOp = (typeof DELIVERY_OPS)[number];
export type RestartPolicy = "now" | "next_restart";

const ID = /^[A-Za-z0-9_-]{1,64}$/;
export const PACK_ID_RE = /^mp_[A-Za-z0-9]{12}$/;
const VERSION_ID_RE = /^[A-Za-z0-9._-]{1,64}$/;
const SHA256_RE = /^[0-9a-f]{64}$/;
const ACK_RE = /^[A-Za-z0-9_.:/-]{1,160}$/;
export const MAX_ACKS = 60;

/** A stored Mod Pack version the worker re-reads (and re-verifies by sha256) from the host's pack store. */
export type PackRef = { packId: string; versionId: string; sha256: string };

export type DeliveryPayload = {
  v: 1;
  op: DeliveryOp;
  /** deliver: the finished build (one version of a Cyrus mod). */
  buildId?: string;
  /** uninstall: the Cyrus project whose delivery record is removed. */
  projectId?: string;
  /** The host's install row for this mod on this server (Nxeon: ServerMod), moved to its final state by the worker. */
  serverModId?: string;
  /** The install row's state before this request (restored when the delivery is refused or rolled back). */
  prev?: { status: string; versionId: string | null } | null;
  restartPolicy: RestartPolicy;
  /** Idempotency key (see deliveryKey). */
  key?: string;
  /** Warning finding ids / acknowledgement ids the customer accepted (recorded; passed to the orchestrator). */
  acknowledge?: string[];
  /** modpack_install: the stored pack version. modpack_uninstall: only packId. */
  pack?: PackRef;
  packId?: string;
  /** Who asked (audit). */
  requestedBy?: string;
};

const str = (v: unknown, re: RegExp) => (typeof v === "string" && re.test(v) ? v : undefined);

/** Validate a payload object (the inner `cyrusDelivery` value). null = not a valid delivery payload. */
export function parseDeliveryPayload(p: unknown): DeliveryPayload | null {
  if (!p || typeof p !== "object" || Array.isArray(p)) return null;
  const o = p as Record<string, unknown>;
  if (o.v !== DELIVERY_PAYLOAD_VERSION || !DELIVERY_OPS.includes(o.op as DeliveryOp)) return null;
  const op = o.op as DeliveryOp;
  const out: DeliveryPayload = { v: 1, op, restartPolicy: o.restartPolicy === "next_restart" ? "next_restart" : "now" };
  const buildId = str(o.buildId, ID), projectId = str(o.projectId, ID), serverModId = str(o.serverModId, ID), key = str(o.key, /^[a-z]_[0-9a-f]{40}$/), requestedBy = str(o.requestedBy, ID);
  if (buildId) out.buildId = buildId;
  if (projectId) out.projectId = projectId;
  if (serverModId) out.serverModId = serverModId;
  if (key) out.key = key;
  if (requestedBy) out.requestedBy = requestedBy;
  if (o.prev && typeof o.prev === "object") {
    const pr = o.prev as Record<string, unknown>;
    if (typeof pr.status === "string" && /^[A-Z_]{1,20}$/.test(pr.status)) out.prev = { status: pr.status, versionId: str(pr.versionId, ID) ?? null };
  }
  if (Array.isArray(o.acknowledge)) {
    const acks = o.acknowledge.filter((a): a is string => typeof a === "string" && ACK_RE.test(a)).slice(0, MAX_ACKS);
    if (acks.length) out.acknowledge = [...new Set(acks)];
  }
  if (o.pack && typeof o.pack === "object") {
    const pk = o.pack as Record<string, unknown>;
    const packId = str(pk.packId, PACK_ID_RE), versionId = str(pk.versionId, VERSION_ID_RE), sha = str(pk.sha256, SHA256_RE);
    if (packId && versionId && sha) out.pack = { packId, versionId, sha256: sha };
  }
  const packId = str(o.packId, PACK_ID_RE);
  if (packId) out.packId = packId;
  if (op === "deliver" && !out.buildId) return null;
  if (op === "uninstall" && !out.projectId) return null;
  if (op === "modpack_install" && !out.pack) return null;
  if (op === "modpack_uninstall" && !out.packId) return null;
  return out;
}

/** The discriminator on a whole job payload: null for every ordinary GAME_MOD_SYNC payload. */
export function readDeliveryPayload(payload: unknown): DeliveryPayload | null {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) return null;
  return parseDeliveryPayload((payload as Record<string, unknown>).cyrusDelivery);
}

const sha = (s: string) => createHash("sha256").update(s).digest("hex");
/** A client-supplied Idempotency-Key header value (8..128 printable, no spaces). */
export const CLIENT_KEY_RE = /^[A-Za-z0-9_.:-]{8,128}$/;

/**
 * Idempotency key stored on the job. A client key ("c_") is scoped to the account (two accounts can never collide) and
 * replays the same job whatever its state; a derived key ("d_") covers double-clicks: it is reused only while that job
 * is still queued or running, so a retry after a finished delivery creates a new job.
 */
export function deliveryKey(a: { userId: string; serverId: string; op: DeliveryOp; subject: string; restartPolicy: RestartPolicy; clientKey?: string | null }): { key: string; kind: "client" | "derived" } {
  if (a.clientKey && CLIENT_KEY_RE.test(a.clientKey)) return { key: `c_${sha(`${a.userId}\n${a.clientKey}`).slice(0, 40)}`, kind: "client" };
  return { key: `d_${sha([a.userId, a.serverId, a.op, a.subject, a.restartPolicy].join("\n")).slice(0, 40)}`, kind: "derived" };
}
/** Whether an existing job with the same key answers this request (instead of a new job). */
export function reuseExisting(kind: "client" | "derived", jobStatus: string): boolean {
  return kind === "client" || jobStatus === "QUEUED" || jobStatus === "RUNNING";
}

// ------------------------------------------------------------------------------------------------ what would be delivered

export type DeliveryPart = { kind: "plugin" | "resource_pack" | "datapack" | "worldgen" | "creature"; name: string; delivered: boolean; reason?: string };
export type DeliveryAck = { id: "restart" | "worldgen"; text: string };
export type PartsView = { parts: DeliveryPart[]; restart: boolean; worldgen: boolean; acks: DeliveryAck[]; deliverable: boolean };

export const ACK_TEXT: Record<DeliveryAck["id"], string> = {
  restart: "Your server restarts to load the change (players are disconnected for about a minute). If it does not come up healthy, everything is put back as it was and the server is restarted again.",
  worldgen: "This adds or changes world generation. It takes effect at the restart and only new chunks use it. If the pack stops the server from starting, the delivery is rolled back automatically.",
};

type StoredAssets = { status?: string; loader?: unknown; datapacks?: { name: string; apply?: string; worldgen?: boolean }[]; creatures?: { name: string }[] };
/** The delivery-relevant part of ModBuild.result.assets (same shape check as lib/cyrus/assets/sync.ts readBuildAssets; kept local so this module stays light). */
function storedAssets(result: unknown): StoredAssets | null {
  const a = (result as { assets?: unknown } | null)?.assets as (StoredAssets & { textures?: unknown; namespace?: unknown }) | undefined;
  if (!a || typeof a !== "object" || !Array.isArray(a.textures) || typeof a.namespace !== "string") return null;
  return a;
}

/** The parts of one finished build the orchestrator would carry with these switches (mirrors deliverMod's own filter). */
export function deliveryParts(result: unknown, pluginName: string | null, env: Env, restartPolicy: RestartPolicy = "now"): PartsView {
  const sw = switches(env);
  const a = storedAssets(result);
  const parts: DeliveryPart[] = [];
  if (pluginName) parts.push({ kind: "plugin", name: pluginName, delivered: true });
  if (a?.status === "ready" && a.loader) parts.push(sw.managed ? { kind: "resource_pack", name: "resource pack", delivered: true } : { kind: "resource_pack", name: "resource pack", delivered: false, reason: "managed plugins (the Pack Loader) are switched off" });
  else if (a?.status === "unhosted") parts.push({ kind: "resource_pack", name: "resource pack", delivered: false, reason: "the resource pack is not hosted here" });
  for (const d of a?.datapacks ?? []) {
    const kind = d.worldgen ? "worldgen" : "datapack";
    if (!sw.datapacks) parts.push({ kind, name: d.name, delivered: false, reason: "data pack delivery is switched off" });
    else if (d.worldgen && !sw.worldgen) parts.push({ kind, name: d.name, delivered: false, reason: "world generation is switched off" });
    else parts.push({ kind, name: d.name, delivered: true });
  }
  for (const c of a?.creatures ?? []) parts.push(sw.creatures ? { kind: "creature", name: c.name, delivered: true } : { kind: "creature", name: c.name, delivered: false, reason: "creature delivery is switched off" });
  const delivered = parts.filter((p) => p.delivered);
  const worldgen = delivered.some((p) => p.kind === "worldgen");
  // a plugin jar, managed plugins, registry data packs, worldgen and creatures all load at start (plan.ts planApply)
  const restart = delivered.some((p) => p.kind !== "datapack") || (a?.datapacks ?? []).some((d) => d.apply === "restart" && delivered.some((p) => p.name === d.name));
  const acks: DeliveryAck[] = [];
  if (restart && restartPolicy === "now") acks.push({ id: "restart", text: ACK_TEXT.restart });
  if (worldgen) acks.push({ id: "worldgen", text: ACK_TEXT.worldgen });
  return { parts, restart, worldgen, acks, deliverable: delivered.length > 0 };
}

/** The acknowledgement ids in `required` that `given` does not contain. */
export const missingAcks = (required: { id: string }[], given: string[]) => required.filter((r) => !given.includes(r.id));

// ------------------------------------------------------------------------------------------------ status read model

export type DeliveryState = "queued" | "running" | DeliveryOutcome | "failed";
export type DeliveryStatus = {
  jobId: string;
  serverId: string | null;
  op: DeliveryOp | null;
  subject: { buildId?: string; projectId?: string; packId?: string; versionId?: string };
  state: DeliveryState;
  /** Still queued or running: poll again. */
  pending: boolean;
  /** true = it worked, false = it did not, null = not finished. */
  ok: boolean | null;
  /** One customer-safe sentence. */
  headline: string;
  /** Something on the server may not be as it was before (rollback incomplete): show prominently, support is needed. */
  needsAttention: boolean;
  error: string | null;
  failedStep: string | null;
  steps: { step: string; status: string; detail: string }[];
  apply: { mode: string; restarted: boolean; reloaded: boolean; reasons: string[] } | null;
  health: { ok: boolean; problems: string[] } | null;
  rollback: { ok: boolean; restored: number; removed: number; mismatches: number; restarted: boolean; cameBackHealthy: boolean | null } | null;
  conflicts: { blocking: string[]; warnings: { id: string; message: string }[] } | null;
  notes: string[];
  keptWorldFolders: string[];
  createdAt: string;
  updatedAt: string;
};

type JobRow = { id: string; serverId: string | null; status: string; error: string | null; payload: unknown; createdAt: Date; updatedAt: Date };
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const clip = (s: unknown, n = 400) => (typeof s === "string" ? s.slice(0, n) : null);
const STEP_WORDS: Record<string, string> = { open: "opening the server", recover_check: "the safety check", preflight: "the pre-checks", managed: "installing a managed plugin", host_pack: "hosting the resource pack", pack_config: "the pack config", place: "placing the files", apply: "applying the change", health: "the health check", handoff: "the model pack hand-off", record: "recording the delivery", commit: "finishing" };

function headlineFor(state: DeliveryState, r: Partial<DeliveryResult>, jobError: string | null): string {
  const step = r.failedStep ? STEP_WORDS[r.failedStep] ?? r.failedStep : null;
  switch (state) {
    case "queued": return "Waiting for the server to be free.";
    case "running": return "Delivering to your server.";
    case "delivered": return r.apply?.mode === "restart" ? "Delivered: the server restarted and came up healthy." : r.apply?.mode === "reload" ? "Delivered: the data was reloaded and checked." : "Delivered.";
    case "updated": return r.apply?.mode === "restart" ? "Updated: the server restarted and came up healthy." : "Updated.";
    case "uninstalled": return (r.keptWorldFolders?.length ?? 0) > 0 ? "Removed. Generated dimension folders were kept." : "Removed.";
    case "unchanged": return "Already up to date: nothing changed.";
    case "pending_restart": return "Placed on the server: it takes effect at the next restart.";
    case "refused": return `Not delivered${step ? ` (${step})` : ""}: nothing on your server was changed.`;
    case "rolled_back": return `The delivery failed at ${step ?? "a step"} and was rolled back: your server is back on its previous state${r.rollback?.restarted ? " and came up again" : ""}.`;
    case "rollback_incomplete": return `The delivery failed at ${step ?? "a step"} and the automatic rollback could not fully restore your server. Do not restart it yet: contact support.`;
    case "failed": return `The delivery did not run: ${(jobError ?? "the job failed").slice(0, 200)}`;
  }
}

/** One delivery job row -> the portal's view of it. */
export function deliveryStatus(job: JobRow): DeliveryStatus {
  const p = obj(job.payload);
  const req = parseDeliveryPayload(p.cyrusDelivery);
  const res = obj(obj(p.result).cyrusDelivery) as Partial<DeliveryResult> & Record<string, unknown>;
  const hasResult = typeof res.outcome === "string";
  const state: DeliveryState = hasResult ? (res.outcome as DeliveryOutcome)
    : job.status === "QUEUED" ? "queued" : job.status === "RUNNING" ? "running" : "failed";
  const rb = res.rollback ? obj(res.rollback) : null;
  const health = res.health ? obj(res.health) : null;
  const conflicts = res.conflicts ? obj(res.conflicts) : null;
  const subject = { ...(req?.buildId ? { buildId: req.buildId } : {}), ...(req?.projectId ? { projectId: req.projectId } : {}), ...(req?.pack ? { packId: req.pack.packId, versionId: req.pack.versionId } : req?.packId ? { packId: req.packId } : {}) };
  // a DONE job without a stored result cannot be judged: never shown as a success
  const jobError = clip(job.error, 300) ?? (job.status === "DONE" && !hasResult ? "no delivery result was recorded" : null);
  return {
    jobId: job.id, serverId: job.serverId, op: req?.op ?? null, subject, state,
    pending: !hasResult && (job.status === "QUEUED" || job.status === "RUNNING"),
    ok: hasResult ? res.ok === true : job.status === "QUEUED" || job.status === "RUNNING" ? null : false,
    headline: headlineFor(state, res, jobError),
    needsAttention: state === "rollback_incomplete",
    error: hasResult ? clip(res.error) : state === "failed" ? jobError : null,
    failedStep: clip(res.failedStep, 40),
    steps: Array.isArray(res.steps) ? (res.steps as { step: string; status: string; detail?: string }[]).slice(0, 40).map((s) => ({ step: String(s.step), status: String(s.status), detail: clip(s.detail, 300) ?? "" })) : [],
    apply: res.apply ? { mode: String(res.apply.mode), restarted: res.apply.restarted === true, reloaded: res.apply.reloaded === true, reasons: (res.apply.reasons ?? []).slice(0, 8) } : null,
    health: health ? { ok: health.ok === true, problems: Array.isArray(health.problems) ? (health.problems as string[]).slice(0, 10).map((x) => String(x).slice(0, 300)) : [] } : null,
    rollback: rb ? { ok: rb.ok === true, restored: Number(rb.restored ?? 0), removed: Number(rb.removed ?? 0), mismatches: Array.isArray(rb.mismatches) ? rb.mismatches.length : 0, restarted: rb.restarted === true, cameBackHealthy: rb.health ? obj(rb.health).ok === true : null } : null,
    conflicts: conflicts ? { blocking: Array.isArray(conflicts.blocking) ? (conflicts.blocking as { message: string }[]).slice(0, 10).map((b) => String(b.message).slice(0, 300)) : [], warnings: Array.isArray(conflicts.warnings) ? (conflicts.warnings as { id: string; message: string }[]).slice(0, 20).map((w) => ({ id: String(w.id), message: String(w.message).slice(0, 300) })) : [] } : null,
    notes: Array.isArray(res.notes) ? (res.notes as string[]).slice(0, 12).map((n) => String(n).slice(0, 300)) : [],
    keptWorldFolders: Array.isArray(res.keptWorldFolders) ? (res.keptWorldFolders as string[]).slice(0, 20) : [],
    createdAt: job.createdAt.toISOString(), updatedAt: job.updatedAt.toISOString(),
  };
}

/** Compact, JSON-safe result for the job row (no buffers, bounded text). */
export function compactResult(r: DeliveryResult): Record<string, unknown> {
  return JSON.parse(JSON.stringify({ ...r, record: r.record ?? null, health: r.health ? { ok: r.health.ok, problems: r.health.problems, report: r.health.report ? { ...r.health.report, errorLines: r.health.report.errorLines.slice(0, 10) } : null } : undefined, steps: r.steps.map((s) => ({ ...s, detail: s.detail.slice(0, 300) })) }));
}

// Cyrus delivery (wiring phase 2): request a delivery of a finished build (plugin + resource pack + data packs + world
// generation + creatures, each behind its own switch) to one of the account's servers, or the removal of one; list
// recent deliveries. OFF unless CYRUS_DELIVERY=1 (404). Logic: lib/cyrus/delivery/api.ts (framework-free, tested with
// fakes); Nxeon's queue, lock and install checks: lib/modbuilder/delivery.ts. API contract: docs/CYRUS-DELIVERY-API.md.
import { handleDeliveryList, handleRequestDelivery } from "@/lib/cyrus/delivery/api";
import { realDeliveryApiDeps } from "@/lib/modbuilder/delivery";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(req: Request) {
  return handleDeliveryList(new URL(req.url), realDeliveryApiDeps);
}

export async function POST(req: Request) {
  return handleRequestDelivery(req, realDeliveryApiDeps);
}
// Cyrus delivery status (wiring phase 2): the status read model of one delivery job on one of the account's servers
// (queued, running, delivered, updated, uninstalled, unchanged, pending_restart, refused, rolled_back,
// rollback_incomplete, failed). OFF unless CYRUS_DELIVERY=1 (404).
import { handleDeliveryStatus } from "@/lib/cyrus/delivery/api";
import { realDeliveryApiDeps } from "@/lib/modbuilder/delivery";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(_req: Request, ctx: { params: Promise<{ jobId: string }> }) {
  const { jobId } = await ctx.params;
  return handleDeliveryStatus(jobId, realDeliveryApiDeps);
}
// Cyrus Mod Packs (wiring phase 2): list the account's packs / create one from its Cyrus mods. OFF unless
// CYRUS_MODPACKS=1 (404). Logic: lib/cyrus/modpack/api.ts; Nxeon deps: lib/modbuilder/modpack.ts. Contract:
// docs/CYRUS-DELIVERY-API.md.
import { handleCreate, handleList } from "@/lib/cyrus/modpack/api";
import { realModPackApiDeps } from "@/lib/modbuilder/modpack";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET() {
  return handleList(realModPackApiDeps);
}

export async function POST(req: Request) {
  return handleCreate(req, realModPackApiDeps);
}
// Cyrus Mod Packs: install a pack version on one of the account's servers (a delivery job; CYRUS_DELIVERY=1 too). docs/CYRUS-DELIVERY-API.md. OFF unless CYRUS_MODPACKS=1.
import { handleInstall } from "@/lib/cyrus/modpack/api";
import { realModPackApiDeps } from "@/lib/modbuilder/modpack";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function POST(req: Request, ctx: { params: Promise<{ packId: string }> }) {
  return handleInstall((await ctx.params).packId, req, realModPackApiDeps);
}
// Cyrus Config Studio API v1: thin wrapper; logic + validation + gates in lib/cyrus/config/http.ts.
import { configApiDeps } from "@/lib/cyrus/config/deps";
import { handleConfig } from "@/lib/cyrus/config/http";

export const dynamic = "force-dynamic";

export async function GET(req: Request) { return handleConfig(req, configApiDeps()); }
export async function POST(req: Request) { return handleConfig(req, configApiDeps()); }
// Cyrus r31: the Data Pack + worldgen studio's read model (404 unless CYRUS_DATAPACK_STUDIO=1 and the studios are
// visible to the viewer). Logic in lib/cyrus/datapack/studio-view.ts; nothing is written.
import { db } from "@/lib/db";
import { handleDatapackView, DATAPACK_STUDIO_FLAG } from "@/lib/cyrus/datapack/studio-view";
import { serviceDeps, studioViewer } from "@/lib/cyrus/studios/deps";
import { checkRateLimit } from "@/lib/rate-limit";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(req: Request) {
  const s = serviceDeps(process.env);
  return handleDatapackView(req, {
    on: () => process.env[DATAPACK_STUDIO_FLAG] === "1",
    worldgenOn: () => process.env.CYRUS_WORLDGEN === "1",
    viewer: () => studioViewer(),
    chain: s.chain,
    store: s.store,
    buildIds: async (userId, root) => (await db.modBuild.findMany({ where: { userId, OR: [{ id: root }, { rootBuildId: root }] }, select: { id: true }, take: 200 })).map((b) => b.id),
    rateLimit: (key, max, windowMs) => checkRateLimit(`cyrus:${key}`, { max, windowMs }),
  });
}
// Cyrus designer studio API: the mod's designs + analysis + draft (404 unless the studios are visible AND CYRUS_DESIGNER=1). Logic in lib/cyrus/designer/studio/http.ts.
import { designerApiDeps } from "@/lib/cyrus/designer/studio/deps";
import { handleView } from "@/lib/cyrus/designer/studio/http";
import { designerShipDeps } from "@/lib/modbuilder/designer-ship";

export const dynamic = "force-dynamic";
export async function GET(req: Request) { return handleView(req, designerApiDeps(process.env, designerShipDeps())); }
// Cyrus designer studio API: the autosaved draft (PUT) and discarding it (DELETE). Logic in lib/cyrus/designer/studio/http.ts.
import { designerApiDeps } from "@/lib/cyrus/designer/studio/deps";
import { handleDraftDelete, handleDraftPut } from "@/lib/cyrus/designer/studio/http";

export const dynamic = "force-dynamic";
export async function PUT(req: Request, ctx: { params: Promise<{ projectId: string }> }) { return handleDraftPut(req, await ctx.params, designerApiDeps()); }
export async function DELETE(req: Request, ctx: { params: Promise<{ projectId: string }> }) { return handleDraftDelete(req, await ctx.params, designerApiDeps()); }
// Cyrus wiring phase 2: the HTTP layer behind app/api/cyrus/delivery/v1/** (framework-free: Request in, Response out,
// every outside dependency injected, so the route tests run with fakes and the node-2 real run drives the same code).
// Order of checks on every route: the OFF-by-default switch CYRUS_DELIVERY=1 in the web process (else 404: the
// feature is invisible) -> signed-in Cyrus user (else 404) -> rate limit (429) -> input (400) -> the subject is the
// caller's own (404) -> what would be delivered (409 when nothing can be) -> the host's install checks, the SAME ones
// as the install route (server ownership + compatibility, networking consent, install plan acknowledgements, Test
// Flight block, the real-mods switch) -> the delivery's own acknowledgements (restart, world generation: 409
// needs_ack) -> enqueue (idempotent, one job per server at a time: 409 busy) -> 202 with the status read model.
// The worker re-checks ownership and its own switches before it touches anything (lib/cyrus/delivery/job.ts).
import { deliveryKey, deliveryParts, deliveryStatus, missingAcks, ACK_TEXT, CLIENT_KEY_RE, MAX_ACKS, type DeliveryAck, type DeliveryOp, type DeliveryPayload, type DeliveryStatus, type PartsView, type RestartPolicy } from "./request";
import { DELIVERY_FLAG } from "./plan";
import type { Env } from "./types";

export type DeliveryBuild = { id: string; userId: string; status: string; pluginName: string | null; jarName: string | null; jarPath: string | null; result: unknown; mcVersion: string; rootBuildId: string | null };
export type DeliveryJobRow = { id: string; serverId: string | null; status: string; error: string | null; payload: unknown; createdAt: Date; updatedAt: Date };
export type HostCheck = { ok: true; serverName: string } | { ok: false; status: number; error: string; code?: string; plan?: unknown };
export type EnqueueInput = { userId: string; serverId: string; payload: DeliveryPayload; keyKind: "client" | "derived"; build?: DeliveryBuild; projectRootBuildId?: string | null };
export type EnqueueResult = { ok: true; jobId: string; reused: boolean } | { ok: false; status: number; error: string; code: string };

export type DeliveryApiDeps = {
  env: Env;
  currentUser(): Promise<{ id: string } | null>;
  rateLimit(key: string, max: number, windowMs: number): { ok: boolean; retryAfterSec: number };
  /** The caller's OWN build, or null. */
  build(userId: string, buildId: string): Promise<DeliveryBuild | null>;
  /** The caller's OWN Cyrus project, or null. */
  project(userId: string, projectId: string): Promise<{ id: string; rootBuildId: string | null } | null>;
  /** deliver: the host's install checks (same as the install route). */
  checkInstall(a: { userId: string; build: DeliveryBuild; serverId: string; acked: string[]; acceptCapabilities: string | null }): Promise<HostCheck>;
  /** uninstall / Mod Packs: the server is the caller's, a Minecraft server, running, not being deleted. */
  checkServer(a: { userId: string; serverId: string }): Promise<HostCheck>;
  enqueue(a: EnqueueInput): Promise<EnqueueResult>;
  /** A delivery job on one of the caller's servers, or null. */
  job(userId: string, jobId: string): Promise<DeliveryJobRow | null>;
  jobs(userId: string, f: { serverId?: string; limit: number }): Promise<DeliveryJobRow[]>;
};

/** OWNER: tune. Per account. */
export const DELIVERY_RATE_LIMITS: [string, number, number][] = [["cyrus:deliver:min", 6, 60_000], ["cyrus:deliver:hour", 40, 3_600_000]];
const STATUS_RATE: [string, number, number] = ["cyrus:deliver:status", 120, 60_000];
const ID = /^[A-Za-z0-9_-]{1,64}$/;

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store", "x-robots-tag": "noindex" } });
const NOT_FOUND = () => json(404, { error: "Not found" });
export const deliveryEnabled = (env: Env) => env[DELIVERY_FLAG] === "1";

async function gate(d: DeliveryApiDeps, rl: [string, number, number][]): Promise<{ ok: true; uid: string } | { ok: false; res: Response }> {
  if (!deliveryEnabled(d.env)) return { ok: false, res: NOT_FOUND() };
  const user = await d.currentUser().catch(() => null);
  if (!user) return { ok: false, res: NOT_FOUND() };
  for (const [k, max, win] of rl) {
    const r = d.rateLimit(`${k}:${user.id}`, max, win);
    if (!r.ok) return { ok: false, res: json(429, { error: `Too many requests. Retry in ${r.retryAfterSec}s.`, code: "rate_limited" }) };
  }
  return { ok: true, uid: user.id };
}

export type DeliveryRequestBody = { op?: unknown; buildId?: unknown; projectId?: unknown; serverId?: unknown; restartPolicy?: unknown; acked?: unknown; acceptCapabilities?: unknown; preview?: unknown };
export const readAcks = (v: unknown): string[] => (Array.isArray(v) ? [...new Set(v.filter((a): a is string => typeof a === "string" && /^[A-Za-z0-9_.:/-]{1,160}$/.test(a)))].slice(0, MAX_ACKS) : []);

/**
 * POST /api/cyrus/delivery/v1
 *   { op: "deliver", buildId, serverId, restartPolicy?: "now"|"next_restart", acked?: string[], acceptCapabilities?, preview? }
 *   { op: "uninstall", projectId, serverId, restartPolicy?, acked?, preview? }
 * Header `Idempotency-Key` (optional, 8..128 chars): the same key always answers with the same job.
 * preview: true runs every check and returns what would be delivered + the acknowledgements needed, enqueues nothing.
 */
export async function handleRequestDelivery(req: Request, d: DeliveryApiDeps): Promise<Response> {
  const g = await gate(d, DELIVERY_RATE_LIMITS);
  if (!g.ok) return g.res;
  const uid = g.uid;
  const body = (await req.json().catch(() => null)) as DeliveryRequestBody | null;
  if (!body || typeof body !== "object") return json(400, { error: "Send a JSON body.", code: "bad_body" });
  const op = body.op === "uninstall" ? "uninstall" : body.op === "deliver" || body.op === undefined ? "deliver" : null;
  if (!op) return json(400, { error: "op must be deliver or uninstall (Mod Packs have their own routes).", code: "bad_op" });
  const serverId = typeof body.serverId === "string" && ID.test(body.serverId) ? body.serverId : null;
  if (!serverId) return json(400, { error: "Pick a server.", code: "bad_server" });
  if (body.restartPolicy !== undefined && body.restartPolicy !== "now" && body.restartPolicy !== "next_restart") return json(400, { error: "restartPolicy must be now or next_restart.", code: "bad_policy" });
  const restartPolicy: RestartPolicy = body.restartPolicy === "next_restart" ? "next_restart" : "now";
  const acked = readAcks(body.acked);
  const preview = body.preview === true;
  const rawKey = req.headers.get("idempotency-key");
  if (rawKey !== null && !CLIENT_KEY_RE.test(rawKey)) return json(400, { error: "Idempotency-Key must be 8-128 letters, digits or _.:-", code: "bad_key" });

  let view: PartsView;
  let subject: string;
  let build: DeliveryBuild | undefined;
  let projectRoot: string | null | undefined;
  let check: HostCheck;
  if (op === "deliver") {
    const buildId = typeof body.buildId === "string" && ID.test(body.buildId) ? body.buildId : null;
    if (!buildId) return json(400, { error: "Pick a build.", code: "bad_build" });
    build = (await d.build(uid, buildId)) ?? undefined;
    if (!build || build.userId !== uid) return NOT_FOUND();
    if (build.status !== "succeeded" || !build.jarName || !build.pluginName || !build.jarPath) return json(409, { error: "This build has no finished plugin to deliver.", code: "not_finished" });
    view = deliveryParts(build.result, build.pluginName, d.env, restartPolicy);
    if (!view.deliverable) return json(409, { error: "Nothing in this build can be delivered with the current settings.", code: "nothing_deliverable", parts: view.parts });
    if (restartPolicy === "next_restart" && (view.worldgen || view.parts.some((p) => p.delivered && p.kind === "creature"))) return json(409, { error: "World generation and animated creatures are delivered with a supervised restart, so a broken pack can be rolled back. Choose restart now.", code: "needs_restart", parts: view.parts });
    subject = build.id;
    check = await d.checkInstall({ userId: uid, build, serverId, acked, acceptCapabilities: typeof body.acceptCapabilities === "string" ? body.acceptCapabilities.slice(0, 128) : null });
  } else {
    const projectId = typeof body.projectId === "string" && ID.test(body.projectId) ? body.projectId : null;
    if (!projectId) return json(400, { error: "Pick a mod.", code: "bad_project" });
    const proj = await d.project(uid, projectId);
    if (!proj) return NOT_FOUND();
    projectRoot = proj.rootBuildId;
    subject = proj.id;
    const acks: DeliveryAck[] = restartPolicy === "now" ? [{ id: "restart", text: ACK_TEXT.restart }] : [];
    view = { parts: [], restart: true, worldgen: false, acks, deliverable: true };
    check = await d.checkServer({ userId: uid, serverId });
  }
  const missing = missingAcks(view.acks, acked);
  if (preview) return json(200, { preview: true, op, parts: view.parts, restart: view.restart, acks: view.acks, missingAcks: missing.map((m) => m.id), check: check.ok ? { ok: true, serverName: check.serverName } : { ok: false, error: check.error, code: check.code ?? null, plan: check.plan ?? null } });
  if (!check.ok) return json(check.status, { error: check.error, code: check.code ?? "refused", ...(check.plan ? { plan: check.plan } : {}) });
  if (missing.length) return json(409, { error: "Confirm the steps below first.", code: "needs_ack", acks: missing, parts: view.parts });

  const k = deliveryKey({ userId: uid, serverId, op: op as DeliveryOp, subject, restartPolicy, clientKey: rawKey });
  const payload: DeliveryPayload = {
    v: 1, op, restartPolicy, key: k.key, requestedBy: uid,
    ...(op === "deliver" ? { buildId: subject } : { projectId: subject }),
    ...(acked.length ? { acknowledge: acked } : {}),
  };
  const q = await d.enqueue({ userId: uid, serverId, payload, keyKind: k.kind, build, projectRootBuildId: projectRoot });
  if (!q.ok) return json(q.status, { error: q.error, code: q.code });
  const row = await d.job(uid, q.jobId);
  return json(q.reused ? 200 : 202, { jobId: q.jobId, reused: q.reused, parts: view.parts, status: row ? deliveryStatus(row) : null });
}

/** GET /api/cyrus/delivery/v1/<jobId>: the status read model of one delivery on one of the caller's servers. */
export async function handleDeliveryStatus(jobId: string, d: DeliveryApiDeps): Promise<Response> {
  const g = await gate(d, [STATUS_RATE]);
  if (!g.ok) return g.res;
  if (!ID.test(jobId)) return NOT_FOUND();
  const row = await d.job(g.uid, jobId);
  if (!row) return NOT_FOUND();
  return json(200, { status: deliveryStatus(row) });
}

/** GET /api/cyrus/delivery/v1?serverId=<id>: the caller's recent deliveries (newest first, at most 25). */
export async function handleDeliveryList(url: URL, d: DeliveryApiDeps): Promise<Response> {
  const g = await gate(d, [STATUS_RATE]);
  if (!g.ok) return g.res;
  const sid = url.searchParams.get("serverId");
  if (sid !== null && !ID.test(sid)) return json(400, { error: "Bad server id.", code: "bad_server" });
  const rows = await d.jobs(g.uid, { ...(sid ? { serverId: sid } : {}), limit: 25 });
  return json(200, { deliveries: rows.map(deliveryStatus) satisfies DeliveryStatus[] });
}

