// Cyrus wiring phase 2: Nxeon's side of the DELIVERY ENQUEUE (the deps of lib/cyrus/delivery/api.ts). SERVER ONLY.
// Lives next to lib/modbuilder/install.ts because it is the same kind of platform code: Nxeon's job queue, the
// per-server job lock, the ServerMod install row and the install route's checks. The Cyrus side stays host-neutral.
//
// What one request does (route app/api/cyrus/delivery/v1):
//   1. the install route's checks, unchanged (installEligibility: ownership, Minecraft + Paper/Purpur, running, the
//      Test Flight block, ENABLE_REAL_GAMEMODS; capability consent; the install plan acknowledgements);
//   2. under the per-server advisory lock (lib/job-guard.ts): ownership again, the idempotency key (a job with the same
//      key answers the request), one job per server at a time, the ServerMod row moved to INSTALLING / UPDATING /
//      REMOVING with its previous state recorded in the payload, and ONE GAME_MOD_SYNC job whose payload carries the
//      `cyrusDelivery` discriminator (the worker hands it to the orchestrator, worker/cyrus-delivery.ts);
//   3. an audit row `cyrus.delivery.requested`.
// Off unless CYRUS_DELIVERY=1 in the web process (the API answers 404); the worker refuses unless its own
// CYRUS_DELIVERY=1, and each part keeps its own switch there.
import type { ModBuild } from "@prisma/client";
import { db } from "../db";
import { withServerJobLock } from "../job-guard";
import { checkRateLimit } from "../rate-limit";
import { getSettingBool } from "../settings";
import { modBuilderUser } from "./access";
import { installEligibility, modBuilderServers } from "./install";
import { ensureCyrusGameMod } from "../cyrus-mods/registry";
import { syncCyrusModPage } from "../cyrus-mods/pages";
import { capabilityGate } from "../cyrus/capabilities";
import { installPlansFor } from "../cyrus/lifecycle/server";
import { confirmPlan } from "../cyrus/lifecycle/install-plan";
import { reuseExisting } from "../cyrus/delivery/request";
import type { DeliveryApiDeps, DeliveryBuild, EnqueueInput, EnqueueResult, HostCheck } from "../cyrus/delivery/api";
import { SANDBOX } from "../sandbox";
import { CYRUS_SOURCE } from "../cyrus/source";

const DELIVERY_WHERE = { type: "GAME_MOD_SYNC" as const, payload: { path: ["cyrusDelivery", "v"], equals: 1 } };
const JOB_SELECT = { id: true, serverId: true, status: true, error: true, payload: true, createdAt: true, updatedAt: true } as const;

async function checkInstall(a: { userId: string; build: DeliveryBuild; serverId: string; acked: string[]; acceptCapabilities: string | null }): Promise<HostCheck> {
  const build = (await db.modBuild.findUnique({ where: { id: a.build.id } })) as ModBuild | null;
  if (!build || build.userId !== a.userId) return { ok: false, status: 404, error: "Not found", code: "not_found" };
  const gate = capabilityGate({
    capabilities: (build.result as { capabilities?: unknown } | null)?.capabilities ?? null,
    networkingEnabled: await getSettingBool("cyrus_mod_networking_enabled"),
    acceptedSha256: a.acceptCapabilities,
  });
  if (!gate.ok) return { ok: false, status: gate.status, error: gate.error, code: gate.code };
  const sp = (await installPlansFor(build, a.userId)).plans.find((p) => p.server.id === a.serverId);
  if (sp) {
    const c = confirmPlan(sp.plan, a.acked);
    if (!c.ok) return { ok: false, status: 409, error: c.error, code: "needs_plan_ack", plan: sp.plan };
  }
  const el = await installEligibility(build, a.userId, a.serverId);
  if (!el.ok) return { ok: false, status: 409, error: el.error, code: "not_eligible" };
  return { ok: true, serverName: el.facts.name };
}

export async function checkServer(a: { userId: string; serverId: string }): Promise<HostCheck> {
  const s = (await modBuilderServers(a.userId)).find((x) => x.id === a.serverId);
  if (!s) return { ok: false, status: 404, error: "Server not found.", code: "not_found" };
  if (!s.compatible) return { ok: false, status: 409, error: s.reason || "That server can't take this change.", code: "not_eligible" };
  if (!SANDBOX && process.env.ENABLE_REAL_GAMEMODS !== "1") return { ok: false, status: 409, error: "One-click mod changes are paused right now, so nothing was changed.", code: "paused" };
  return { ok: true, serverName: s.name };
}

const fail = (status: number, error: string, code: string): EnqueueResult => ({ ok: false, status, error, code });

export async function enqueueCyrusDelivery(a: EnqueueInput): Promise<EnqueueResult> {
  const { userId, serverId, payload } = a;
  let modId: string | null = null;
  if (payload.op === "deliver") {
    const root = a.build?.rootBuildId ?? a.build?.id;
    if (!root) return fail(400, "Pick a build.", "bad_build");
    await syncCyrusModPage(root).catch(() => null);
    const gm = await ensureCyrusGameMod(root);
    if (!gm) return fail(409, "This build has no plugin file to install.", "no_plugin");
    modId = gm.id;
  } else if (payload.op === "uninstall" && a.projectRootBuildId) {
    modId = (await db.gameMod.findFirst({ where: { source: CYRUS_SOURCE, sourceId: a.projectRootBuildId }, select: { id: true } }))?.id ?? null;
  }
  const r = await withServerJobLock(serverId, async (tx): Promise<EnqueueResult> => {
    const srv = await tx.server.findUnique({ where: { id: serverId }, select: { userId: true, status: true } });
    if (!srv || srv.userId !== userId || srv.status === "DELETING") return fail(404, "Server not found.", "not_found");
    if (payload.key) {
      const same = await tx.job.findFirst({ where: { type: "GAME_MOD_SYNC", serverId, payload: { path: ["cyrusDelivery", "key"], equals: payload.key } }, orderBy: { createdAt: "desc" }, select: { id: true, status: true } });
      if (same && reuseExisting(a.keyKind, same.status)) return { ok: true, jobId: same.id, reused: true };
    }
    const inflight = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
    if (inflight > 0) return fail(409, "Another operation is already running on this server. Try again when it finishes.", "busy");
    let serverModId: string | undefined;
    let prev: { status: string; versionId: string | null } | null = null;
    if (modId) {
      const ex = await tx.serverMod.findUnique({ where: { serverId_modId: { serverId, modId } } });
      if (payload.op === "deliver") {
        if (ex?.status === "DISABLED") return fail(409, "This mod is switched off on that server. Switch it on in the server's Mods tab first.", "disabled");
        if (ex && !["INSTALLED", "FAILED", "REMOVED"].includes(ex.status)) return fail(409, `This mod is busy on that server (${ex.status.toLowerCase()}). Try again in a moment.`, "busy");
        prev = ex ? { status: ex.status, versionId: ex.versionId } : null;
        const to = ex?.status === "INSTALLED" ? "UPDATING" : "INSTALLING";
        const row = await tx.serverMod.upsert({ where: { serverId_modId: { serverId, modId } }, create: { serverId, modId, status: to, error: null, targetVersionId: payload.buildId }, update: { status: to, error: null, targetVersionId: payload.buildId } });
        serverModId = row.id;
      } else if (ex) {
        if (!["INSTALLED", "FAILED"].includes(ex.status)) return fail(409, `This mod is ${ex.status.toLowerCase()} on that server. Try again in a moment.`, "busy");
        prev = { status: ex.status, versionId: ex.versionId };
        await tx.serverMod.update({ where: { id: ex.id }, data: { status: "REMOVING", error: null } });
        serverModId = ex.id;
      }
    }
    const job = await tx.job.create({ data: { type: "GAME_MOD_SYNC", serverId, payload: { cyrusDelivery: { ...payload, ...(serverModId ? { serverModId, prev } : {}) } } }, select: { id: true } });
    return { ok: true, jobId: job.id, reused: false };
  });
  if (r.ok && !r.reused) {
    await db.auditLog.create({ data: { userId, action: "cyrus.delivery.requested", detail: `${serverId} job=${r.jobId} ${payload.op} ${payload.buildId ?? payload.projectId ?? payload.pack?.packId ?? payload.packId ?? ""} restart=${payload.restartPolicy}${payload.acknowledge?.length ? ` acked=${payload.acknowledge.length}` : ""}`.slice(0, 900) } }).catch(() => {});
  }
  return r;
}

export const realDeliveryApiDeps: DeliveryApiDeps = {
  env: process.env,
  currentUser: async () => { const u = await modBuilderUser().catch(() => null); return u ? { id: u.id } : null; },
  rateLimit: (key, max, windowMs) => checkRateLimit(key, { max, windowMs }),
  build: (userId, id) => db.modBuild.findFirst({ where: { id, userId } }),
  project: (userId, id) => db.cyrusProject.findFirst({ where: { id, userId }, select: { id: true, rootBuildId: true } }),
  checkInstall,
  checkServer,
  enqueue: enqueueCyrusDelivery,
  job: (userId, id) => db.job.findFirst({ where: { id, ...DELIVERY_WHERE, server: { userId } }, select: JOB_SELECT }),
  jobs: (userId, f) => db.job.findMany({ where: { ...DELIVERY_WHERE, server: { userId }, ...(f.serverId ? { serverId: f.serverId } : {}) }, orderBy: { createdAt: "desc" }, take: f.limit, select: JOB_SELECT }),
};

// Cyrus wiring phase 2: the delivery JOB body (worker side), host-neutral. worker/cyrus-delivery.ts supplies Nxeon's
// deps (database rows, the SSH-backed DeliveryHost, the install row update); tests and the node-2 real run supply
// in-memory ones. Flow for one GAME_MOD_SYNC job carrying the `cyrusDelivery` payload:
//   payload valid? -> CYRUS_DELIVERY=1 in THIS process? -> server exists -> the subject belongs to the server's owner
//   -> assemble + verify the release from the stored build (releaseFromBuild), or open + verify the stored Mod Pack
//   version (and require every open warning acknowledged) -> the orchestrator (deliverMod / uninstallMod /
//   deliverModPack / uninstallModPack) -> store the compact result on the job -> move the install row to its final state (restored to its
//   previous state when the delivery was refused or rolled back) -> audit -> throw when it did not succeed (the job
//   is then FAILED, never retried: a retry would only repeat a refusal or a rollback).
import { deliverMod, deliverModPack, uninstallMod, uninstallModPack } from "./orchestrator";
import { releaseFromBuild, type BuildFacts, type DatapackAssetRow } from "./release";
import { DELIVERY_FLAG } from "./plan";
import { compactResult, readDeliveryPayload, type DeliveryPayload, type PackRef } from "./request";
import type { NxPack } from "../modpack/manifest";
import type { DeliveryHost, DeliveryResult, Env } from "./types";

export type DeliveryJob = { id: string; serverId: string | null; payload: unknown };
export type DeliveryBuildRow = BuildFacts & { userId: string; status: string; jarPath: string | null };
export type DeliveryServerRow = { id: string; userId: string };

export type InstallRowUpdate =
  | { kind: "delivered"; serverModId: string; buildId: string; jarName: string | null }
  | { kind: "removed"; serverModId: string }
  | { kind: "restore"; serverModId: string; prev: { status: string; versionId: string | null }; error: string }
  | { kind: "failed"; serverModId: string; error: string };

export type DeliveryJobDeps<S extends DeliveryServerRow = DeliveryServerRow> = {
  env: Env;
  server(serverId: string): Promise<S | null>;
  build(buildId: string): Promise<DeliveryBuildRow | null>;
  readJar(jarPath: string): Promise<Buffer | null>;
  projectForRoot(rootBuildId: string): Promise<{ id: string; namespace: string; userId: string } | null>;
  project(projectId: string): Promise<{ id: string; namespace: string; userId: string; rootBuildId: string | null } | null>;
  datapackAssets(revisionId: string): Promise<DatapackAssetRow[]>;
  host(server: S, ctx: { rootBuildId: string | null; buildId?: string | null }): DeliveryHost;
  storeResult(jobId: string, result: Record<string, unknown>): Promise<void>;
  audit(userId: string, action: string, detail: string): Promise<void>;
  installRow?(u: InstallRowUpdate): Promise<void>;
  /** Mod Packs: the OWNER's stored pack version, opened and verified (sha256, manifest, pack + version id). */
  modpack?(userId: string, ref: PackRef): Promise<{ ok: true; manifest: NxPack; archive: Map<string, Buffer> } | { ok: false; error: string }>;
  noRetry(jobId: string): Promise<void>;
};

export class DeliveryJobError extends Error {}

/** Final install-row state for a finished delivery (pure). */
export function installRowUpdate(p: DeliveryPayload, r: DeliveryResult, jarName: string | null): InstallRowUpdate | null {
  if (!p.serverModId) return null;
  const err = `${r.outcome === "rolled_back" ? "Rolled back: " : r.outcome === "rollback_incomplete" ? "Rollback incomplete: " : "Not delivered: "}${r.error ?? "failed"}`.slice(0, 900);
  if (r.ok) {
    if (p.op === "uninstall") return { kind: "removed", serverModId: p.serverModId };
    return { kind: "delivered", serverModId: p.serverModId, buildId: p.buildId!, jarName };
  }
  // refused / rolled back: the server is as it was, so the row is too. Incomplete rollback: the row says FAILED.
  if (r.outcome !== "rollback_incomplete" && p.prev) return { kind: "restore", serverModId: p.serverModId, prev: p.prev, error: err };
  return { kind: "failed", serverModId: p.serverModId, error: err };
}

async function refuse<S extends DeliveryServerRow>(job: DeliveryJob, deps: DeliveryJobDeps<S>, p: DeliveryPayload | null, msg: string): Promise<never> {
  await deps.noRetry(job.id);
  if (p?.serverModId && p.prev) await deps.installRow?.({ kind: "restore", serverModId: p.serverModId, prev: p.prev, error: `Not delivered: ${msg}`.slice(0, 900) }).catch(() => {});
  else if (p?.serverModId) await deps.installRow?.({ kind: "failed", serverModId: p.serverModId, error: `Not delivered: ${msg}`.slice(0, 900) }).catch(() => {});
  throw new DeliveryJobError(`cyrus delivery: ${msg}`);
}

export async function runDeliveryJob<S extends DeliveryServerRow>(job: DeliveryJob, deps: DeliveryJobDeps<S>): Promise<DeliveryResult> {
  const p = readDeliveryPayload(job.payload);
  if (!p || !job.serverId) return refuse(job, deps, p, "bad payload");
  if (deps.env[DELIVERY_FLAG] !== "1") return refuse(job, deps, p, `Cyrus delivery is switched off (${DELIVERY_FLAG} is not 1); nothing was changed`);
  const server = await deps.server(job.serverId);
  if (!server) return refuse(job, deps, p, `server ${job.serverId} not found`);
  if (p.requestedBy && p.requestedBy !== server.userId) return refuse(job, deps, p, "the request does not come from the server's owner");
  let result: DeliveryResult;
  let jarName: string | null = null;
  if (p.op === "uninstall") {
    const proj = await deps.project(p.projectId!);
    if (!proj || proj.userId !== server.userId) return refuse(job, deps, p, "the mod belongs to another account");
    result = await uninstallMod(server.id, proj.id, deps.host(server, { rootBuildId: proj.rootBuildId }), { restartPolicy: p.restartPolicy, acknowledge: p.acknowledge });
  } else if (p.op === "deliver") {
    const b = await deps.build(p.buildId!);
    if (!b || b.status !== "succeeded" || !b.jarPath) return refuse(job, deps, p, "the build has no finished plugin");
    if (b.userId !== server.userId) return refuse(job, deps, p, "the build belongs to another account");
    const root = b.rootBuildId ?? b.id;
    const proj = await deps.projectForRoot(root);
    if (proj && proj.userId !== server.userId) return refuse(job, deps, p, "the mod belongs to another account");
    const jar = await deps.readJar(b.jarPath).catch(() => null);
    const revId = (b.result as { assets?: { revisionId?: string | null } } | null)?.assets?.revisionId ?? null;
    const dpRows = revId ? await deps.datapackAssets(revId) : [];
    const rel = releaseFromBuild(b, jar, { project: proj ? { id: proj.id, namespace: proj.namespace } : null, datapackAssets: dpRows });
    if (!rel.ok) return refuse(job, deps, p, rel.error);
    jarName = b.jarName;
    result = await deliverMod(server.id, rel.release, deps.host(server, { rootBuildId: root, buildId: b.id }), { restartPolicy: p.restartPolicy, acknowledge: p.acknowledge });
    result.notes.unshift(...rel.notes);
  } else if (p.op === "modpack_install") {
    if (!deps.modpack) return refuse(job, deps, p, "this worker cannot read Mod Packs");
    // the store is per account: only the server owner's packs can be opened at all
    const pk = await deps.modpack(server.userId, p.pack!);
    if (!pk.ok) return refuse(job, deps, p, pk.error);
    const acked = new Set(p.acknowledge ?? []);
    const open = pk.manifest.conflicts.open.map((o) => o.findingId).filter((id) => !acked.has(id));
    if (open.length) return refuse(job, deps, p, `${open.length} open warning(s) of the pack were not acknowledged (${open.slice(0, 3).join(", ")}); nothing was changed`);
    result = await deliverModPack(server.id, { manifest: pk.manifest, archive: pk.archive }, deps.host(server, { rootBuildId: null }), { restartPolicy: p.restartPolicy, acknowledge: p.acknowledge });
  } else {
    result = await uninstallModPack(server.id, p.packId!, deps.host(server, { rootBuildId: null }), { restartPolicy: p.restartPolicy, acknowledge: p.acknowledge });
  }
  await deps.storeResult(job.id, compactResult(result)).catch((e) => console.error("[cyrus-delivery] result not stored", e));
  const row = installRowUpdate(p, result, jarName);
  if (row) await deps.installRow?.(row).catch((e) => console.error("[cyrus-delivery] install row not updated", e));
  await deps.audit(server.userId, result.ok ? "cyrus.delivery.ok" : "cyrus.delivery.failed", `${server.id} job=${job.id} ${result.op} ${result.outcome} ${result.failedStep ?? ""} ${result.error ?? ""}`.slice(0, 900)).catch(() => {});
  if (!result.ok) { await deps.noRetry(job.id); throw new DeliveryJobError(`Cyrus delivery ${result.outcome}: ${result.error ?? "failed"}`); }
  return result;
}
