// Cyrus R5: assemble a ModRelease (what one mod version delivers) from a finished build's stored facts. Pure: the
// caller (worker/cyrus-delivery.ts, the Test Flight gate) reads the jar bytes and the data pack asset rows and passes
// them in. Every part is re-verified here (jar sha256, data pack rebuilt deterministically to the recorded sha256).
import { createHash } from "node:crypto";
import { rebuildForDelivery } from "../datapack/deliver";
import { readBuildAssets } from "../assets/sync";
import type { ModRelease } from "./types";
import type { StoredCreature } from "../creature/deliver";

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");

export type BuildFacts = { id: string; mcVersion: string; pluginName: string | null; jarName: string | null; jarSha256: string | null; result: unknown; rootBuildId: string | null };
/** A CyrusProjectAsset row of kind "datapack" (provenance: spec, version, packSha256, worldgen). */
export type DatapackAssetRow = { assetKey: string; provenance: unknown };

export function releaseFromBuild(b: BuildFacts, jar: Buffer | null, opts: { project: { id: string; namespace: string } | null; datapackAssets?: DatapackAssetRow[]; label?: string }): { ok: true; release: ModRelease; notes: string[] } | { ok: false; error: string } {
  const notes: string[] = [];
  if (!jar || !b.jarName || !b.pluginName) return { ok: false, error: "the build has no stored plugin jar" };
  if (b.jarSha256 && sha256(jar) !== b.jarSha256) return { ok: false, error: "the stored plugin jar does not match its checksum" };
  const a = readBuildAssets(b.result);
  const project = opts.project ?? (a ? { id: a.projectId, namespace: a.namespace } : null);
  if (!project) return { ok: false, error: "the build has no Cyrus project (namespace), so it cannot be delivered by Cyrus" };
  const pack = a?.status === "ready" && a.loader ? { sha1: a.loader.sha1, url: a.loader.url, prompt: a.loader.prompt, required: a.loader.required, ...(a.pack ? { sha256: a.pack.sha256 } : {}) } : null;
  if (a && a.status === "unhosted") notes.push("the custom resource pack is not hosted here, so it is not delivered");
  const datapacks: ModRelease["datapacks"] = [];
  for (const row of a?.datapacks ?? []) {
    const asset = (opts.datapackAssets ?? []).find((x) => x.assetKey === row.name || (x.provenance as { packSha256?: string } | null)?.packSha256 === row.sha256);
    if (!asset) { notes.push(`data pack ${row.name}: its stored spec was not found, so it is not delivered`); continue; }
    const rb = rebuildForDelivery((asset.provenance ?? {}) as Record<string, unknown>, project.namespace);
    if (!rb.ok) { notes.push(`data pack ${row.name}: ${rb.error}`); continue; }
    if (rb.sha256 !== row.sha256) { notes.push(`data pack ${row.name}: rebuilt bytes differ from the build's record`); continue; }
    datapacks.push({ name: rb.name, zip: rb.zip, sha256: rb.sha256, apply: rb.apply, ...(rb.worldgen ? { worldgen: rb.worldgen } : {}) });
  }
  const creatures = ((a?.creatures ?? []) as unknown as StoredCreature[]).map((c) => ({ name: c.name, key: c.key, spec: c.spec, bbmodelSha256: c.bbmodelSha256, ...(c.paint !== undefined ? { paint: c.paint } : {}) }));
  return {
    ok: true, notes,
    release: {
      projectId: project.id, revisionId: a?.revisionId ?? `build:${b.id}`, modBuildId: b.id, namespace: project.namespace, mcVersion: b.mcVersion, label: opts.label ?? b.pluginName,
      plugin: { pluginName: b.pluginName, jarName: b.jarName, sha256: sha256(jar), bytes: jar }, pack, datapacks, creatures,
    },
  };
}
