// ------------------------------------------------------------------------------------------------ preflight helpers

function datapackCandidate(name: string, zip: Buffer, cyrus: ModEntry["cyrus"]): Promise<ModEntry> {
  const z = indexZip(zip);
  if (!z.ok) throw new Error(`data pack ${name}: ${z.error}`);
  const files = z.zip.entries.filter((e) => !e.dir && e.name.startsWith("data/")).map((e) => ({ path: e.name, read: () => { const r = readEntry(z.zip, e); return r.ok ? r.data : null; } }));
  const mm = z.zip.entries.find((e) => e.name === "pack.mcmeta");
  const mcmeta = mm ? (() => { const r = readEntry(z.zip, mm); return r.ok ? r.data : null; })() : null;
  return indexDatapack(name, "candidate", "zip", files, mcmeta).then((d) => datapackEntry(d, "candidate", { cyrus, changed: true }));
}

function summarize(rep: ReturnType<typeof detectConflicts>, involve: (f: { items: { mod: string }[] }) => boolean): ConflictSummary {
  const mine = rep.findings.filter(involve);
  return {
    blocking: mine.filter((f) => f.severity === "blocking").map((f) => ({ id: f.id, class: f.class, message: f.message })),
    warnings: mine.filter((f) => f.severity !== "blocking").map((f) => ({ id: f.id, class: f.class, severity: f.severity, message: f.message })).slice(0, 50),
    notChecked: rep.notChecked.slice(0, 30),
  };
}

function verifyRelease(r: ModRelease): string | null {
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(r.projectId)) return "bad project id";
  if (!NS_RE.test(r.namespace)) return "bad namespace";
  if (r.plugin) {
    if (!/^[A-Za-z0-9._ -]{1,120}\.jar$/.test(r.plugin.jarName) || r.plugin.jarName.includes("/")) return "bad jar name";
    if (sha256(r.plugin.bytes) !== r.plugin.sha256) return "the plugin jar does not match its recorded sha256";
  }
  if (r.pack?.zip && sha1(r.pack.zip) !== r.pack.sha1) return "the resource pack does not match its recorded sha1";
  if (r.pack && !r.pack.zip && !(r.pack.url && /^https:\/\//.test(r.pack.url))) return "the resource pack has neither bytes nor an https URL";
  for (const d of r.datapacks) {
    if (!/^[a-z0-9_-]{1,40}$/.test(d.name)) return `bad data pack name ${d.name}`;
    if (sha256(d.zip) !== d.sha256) return `data pack ${d.name} does not match its recorded sha256`;
    if (d.worldgen && d.apply !== "restart") return `data pack ${d.name} has world generation and must be applied with a restart`;
  }
  return null;
}

