// Cyrus Mod Packs (wiring phase 2): the HTTP layer behind app/api/cyrus/modpacks/v1/** (framework-free, every outside
// dependency injected; tests run it with fakes). NO UI: the contract is documented in docs/CYRUS-DELIVERY-API.md.
//   POST   /api/cyrus/modpacks/v1/validate          compose + check, store nothing
//   POST   /api/cyrus/modpacks/v1                   create (version 1.0.0)
//   GET    /api/cyrus/modpacks/v1                   the caller's packs
//   GET    /api/cyrus/modpacks/v1/<packId>          one pack (definition, versions, manifest summary)
//   POST   /api/cyrus/modpacks/v1/<packId>/conflicts   { serverId, versionId? }  read-only check against that server
//   POST   /api/cyrus/modpacks/v1/<packId>/install     { serverId, versionId?, acked, restartPolicy? }  -> delivery job
//   POST   /api/cyrus/modpacks/v1/<packId>/uninstall   { serverId, acked, restartPolicy? }             -> delivery job
// Switches: CYRUS_MODPACKS=1 (web) makes the routes exist (else 404); install/uninstall also need CYRUS_DELIVERY=1 (web);
// the worker needs CYRUS_DELIVERY=1 + CYRUS_MODPACK_INSTALL_REAL=1. Members come only from the caller's own finished
// Cyrus builds or a Cyrus build currently installed on one of the caller's servers. Owner recommendation applied:
// an install must acknowledge EVERY open warning (the pack's own and the ones against that server), plus the restart.
// Mod Packs are not plan-gated (owner decision); the delivery job re-checks ownership, the archive sha256 and the
// acknowledgements before it touches the server.
import { buildModPack, type BuildFail, type BuildOk, type MemberInput } from "./builder";
import type { ModPackStore, PackMeta } from "./store";
import { newPackId, sha256Hex, STORE_PACK_ID_RE } from "./store";
import type { InventoryReport } from "../inventory/types";
import type { ConflictReport } from "../conflicts/types";
import { ACK_TEXT, deliveryKey, deliveryStatus, CLIENT_KEY_RE, type DeliveryPayload, type RestartPolicy } from "../delivery/request";
import { deliveryEnabled, readAcks, type DeliveryJobRow, type EnqueueInput, type EnqueueResult, type HostCheck } from "../delivery/api";
import { getVersion } from "../versions/registry";
import type { Env } from "../delivery/types";

export const MODPACKS_FLAG = "CYRUS_MODPACKS";
export const MAX_PACK_MEMBERS = 30;
export const modpacksEnabled = (env: Env) => env[MODPACKS_FLAG] === "1";

export type MembersResult = { ok: true; mcVersion: string; members: MemberInput[]; notes: string[] } | { ok: false; status: number; error: string };
export type ModPackApiDeps = {
  env: Env;
  currentUser(): Promise<{ id: string } | null>;
  rateLimit(key: string, max: number, windowMs: number): { ok: boolean; retryAfterSec: number };
  /** The members one build contributes: the caller's own finished build, or a Cyrus build installed on one of the caller's servers. */
  members(userId: string, buildId: string): Promise<MembersResult>;
  store: ModPackStore;
  /** Read-only inventory of one of the caller's servers + the paths this pack already owns there (its unit record). */
  inventory(userId: string, serverId: string, packId: string): Promise<{ inventory: InventoryReport; ownedPaths: string[] } | null>;
  checkServer(a: { userId: string; serverId: string }): Promise<HostCheck>;
  enqueue(a: EnqueueInput): Promise<EnqueueResult>;
  job(userId: string, jobId: string): Promise<DeliveryJobRow | null>;
  now?(): Date;
  newId?(): string;
};

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store", "x-robots-tag": "noindex" } });
const NOT_FOUND = () => json(404, { error: "Not found" });
const ID = /^[A-Za-z0-9_-]{1,64}$/;
const VERSION_RE = /^\d{1,6}\.\d{1,6}\.\d{1,6}$/;
/** OWNER: tune. Per account. Composing is CPU work (inspect + conflict engine), so it is limited like builds. */
export const MODPACK_RATE_LIMITS: [string, number, number][] = [["cyrus:modpack:min", 10, 60_000], ["cyrus:modpack:hour", 120, 3_600_000]];

async function gate(d: ModPackApiDeps, delivery = false): Promise<{ ok: true; uid: string } | { ok: false; res: Response }> {
  if (!modpacksEnabled(d.env) || (delivery && !deliveryEnabled(d.env))) return { ok: false, res: NOT_FOUND() };
  const user = await d.currentUser().catch(() => null);
  if (!user) return { ok: false, res: NOT_FOUND() };
  for (const [k, max, win] of MODPACK_RATE_LIMITS) {
    const r = d.rateLimit(`${k}:${user.id}`, max, win);
    if (!r.ok) return { ok: false, res: json(429, { error: `Too many requests. Retry in ${r.retryAfterSec}s.`, code: "rate_limited" }) };
  }
  return { ok: true, uid: user.id };
}

type Composition = { name: string; summary?: string; mcVersion: string; buildIds: string[] };
function readComposition(body: Record<string, unknown> | null): Composition | string {
  if (!body) return "Send a JSON body.";
  const name = typeof body.name === "string" ? body.name.trim() : "";
  if (!name || name.length > 80 || /[\u0000-\u001f]/.test(name)) return "Give the pack a name (up to 80 characters).";
  const summary = typeof body.summary === "string" ? body.summary.trim().slice(0, 500) : undefined;
  const mcVersion = typeof body.mcVersion === "string" ? body.mcVersion : "";
  if (!getVersion(mcVersion)) return "Pick a Minecraft version from the list.";
  const raw = Array.isArray(body.members) ? body.members : [];
  const buildIds = raw.map((m) => (m && typeof m === "object" ? (m as { buildId?: unknown }).buildId : m)).filter((x): x is string => typeof x === "string" && ID.test(x));
  if (!buildIds.length || buildIds.length !== raw.length) return "List the mods to include as members: [{ buildId }].";
  if (new Set(buildIds).size !== buildIds.length) return "A mod appears twice.";
  if (buildIds.length > MAX_PACK_MEMBERS) return `A Mod Pack holds at most ${MAX_PACK_MEMBERS} mods.`;
  return { name, ...(summary ? { summary } : {}), mcVersion, buildIds };
}

/** The builder input for a composition (members re-read from the builds on every call: exact build ids). */
async function assemble(d: ModPackApiDeps, uid: string, c: Composition): Promise<{ ok: true; members: MemberInput[]; notes: string[] } | { ok: false; status: number; error: string }> {
  const members: MemberInput[] = [];
  const notes: string[] = [];
  for (const id of c.buildIds) {
    const r = await d.members(uid, id);
    if (!r.ok) return r;
    if (r.mcVersion !== c.mcVersion) notes.push(`${r.members[0]?.label ?? id} was built for ${r.mcVersion}, the pack targets ${c.mcVersion}`);
    members.push(...r.members);
    notes.push(...r.notes);
  }
  return { ok: true, members, notes };
}

export type FindingView = { id: string; class: string; severity: string; message: string; resolution: string; needsAck: boolean };
const findings = (r: ConflictReport | null): FindingView[] => (r?.findings ?? []).map((f) => ({ id: f.id, class: f.class, severity: f.severity, message: f.message.slice(0, 400), resolution: f.resolution.text.slice(0, 400), needsAck: f.severity === "warn" && !f.resolution.auto }));
function buildView(b: BuildOk | BuildFail, notes: string[]) {
  if (!b.ok) return { ok: false as const, code: b.code, errors: b.errors.slice(0, 20), findings: findings(b.report), notes };
  return { ok: true as const, versionId: b.manifest.versionId, members: b.manifest.members.map((m) => ({ id: m.id, kind: m.kind, label: m.label, version: m.version })), counts: b.report.counts, findings: findings(b.report), openWarnings: b.manifest.conflicts.open.map((o) => o.findingId), notChecked: b.report.notChecked.slice(0, 20), compatibility: b.manifest.compatibility, bytes: b.archiveZip.length, notes };
}
const packView = (m: PackMeta) => ({ packId: m.packId, name: m.name, summary: m.summary ?? null, mcVersion: m.mcVersion, members: m.members, versions: m.versions, latest: m.versions[m.versions.length - 1]?.versionId ?? null, createdAt: m.createdAt, updatedAt: m.updatedAt });

async function compose(d: ModPackApiDeps, uid: string, c: Composition, packId: string, extra: { inventory?: InventoryReport; ownedPaths?: string[] } = {}) {
  const a = await assemble(d, uid, c);
  if (!a.ok) return { ok: false as const, res: json(a.status, { error: a.error, code: "bad_member" }) };
  const b = await buildModPack({ packId, name: c.name, summary: c.summary, mcVersion: c.mcVersion, members: a.members, ...extra });
  return { ok: true as const, build: b, notes: a.notes };
}

/** POST /validate: compose and check, nothing stored. 200 { ok, ... } (ok:false = the pack would be refused, with why). */
export async function handleValidate(req: Request, d: ModPackApiDeps): Promise<Response> {
  const g = await gate(d);
  if (!g.ok) return g.res;
  const c = readComposition((await req.json().catch(() => null)) as Record<string, unknown> | null);
  if (typeof c === "string") return json(400, { error: c, code: "bad_body" });
  const r = await compose(d, g.uid, c, "mp_000000000000");
  if (!r.ok) return r.res;
  return json(200, buildView(r.build, r.notes));
}

/** POST /: create the pack (version 1.0.0). 409 when the composition is refused (blocking conflicts, bad members). */
export async function handleCreate(req: Request, d: ModPackApiDeps): Promise<Response> {
  const g = await gate(d);
  if (!g.ok) return g.res;
  const c = readComposition((await req.json().catch(() => null)) as Record<string, unknown> | null);
  if (typeof c === "string") return json(400, { error: c, code: "bad_body" });
  const packId = (d.newId ?? newPackId)();
  const r = await compose(d, g.uid, c, packId);
  if (!r.ok) return r.res;
  if (!r.build.ok) return json(409, { error: "This pack cannot be built as it is.", ...buildView(r.build, r.notes) });
  const now = (d.now ?? (() => new Date()))().toISOString();
  const b = r.build;
  const meta: PackMeta = {
    schema: 1, packId, userId: g.uid, name: c.name, ...(c.summary ? { summary: c.summary } : {}), mcVersion: c.mcVersion, members: c.buildIds.map((buildId) => ({ buildId })),
    versions: [{ versionId: b.manifest.versionId, sha256: sha256Hex(b.archiveZip), bytes: b.archiveZip.length, createdAt: now, openWarnings: b.manifest.conflicts.open.map((o) => o.findingId), blocking: b.report.counts.blocking }],
    createdAt: now, updatedAt: now,
  };
  await d.store.save(meta, { versionId: b.manifest.versionId, zip: b.archiveZip });
  return json(201, { pack: packView(meta), build: buildView(b, r.notes) });
}

export async function handleList(d: ModPackApiDeps): Promise<Response> {
  const g = await gate(d);
  if (!g.ok) return g.res;
  return json(200, { packs: (await d.store.list(g.uid)).map(packView) });
}

export async function handleGet(packId: string, d: ModPackApiDeps): Promise<Response> {
  const g = await gate(d);
  if (!g.ok) return g.res;
  if (!STORE_PACK_ID_RE.test(packId)) return NOT_FOUND();
  const m = await d.store.get(g.uid, packId);
  return m ? json(200, { pack: packView(m) }) : NOT_FOUND();
}

type Target = { meta: PackMeta; versionId: string; sha256: string; openWarnings: string[] };
async function target(d: ModPackApiDeps, uid: string, packId: string, versionId: unknown): Promise<Target | Response> {
  if (!STORE_PACK_ID_RE.test(packId)) return NOT_FOUND();
  const meta = await d.store.get(uid, packId);
  if (!meta) return NOT_FOUND();
  const v = typeof versionId === "string" && VERSION_RE.test(versionId) ? meta.versions.find((x) => x.versionId === versionId) : versionId === undefined ? meta.versions[meta.versions.length - 1] : undefined;
  if (!v) return json(404, { error: "That version of the pack does not exist.", code: "no_version" });
  return { meta, versionId: v.versionId, sha256: v.sha256, openWarnings: v.openWarnings };
}

/** The pack checked against what the server runs now (read-only). */
async function againstServer(d: ModPackApiDeps, uid: string, t: Target, serverId: string) {
  const inv = await d.inventory(uid, serverId, t.meta.packId);
  if (!inv) return { ok: false as const, res: NOT_FOUND() };
  const r = await compose(d, uid, { name: t.meta.name, summary: t.meta.summary, mcVersion: t.meta.mcVersion, buildIds: t.meta.members.map((m) => m.buildId) }, t.meta.packId, { inventory: inv.inventory, ownedPaths: inv.ownedPaths });
  if (!r.ok) return r;
  const view = buildView(r.build, r.notes);
  const blocking = view.findings.filter((f) => f.severity === "blocking");
  const required = [...new Set([...t.openWarnings, ...view.findings.filter((f) => f.needsAck).map((f) => f.id)])];
  return { ok: true as const, view, blocking, required, serverFindings: r.build.ok ? r.build.serverFindings.length : 0 };
}

const readServer = (body: Record<string, unknown> | null) => (body && typeof body.serverId === "string" && ID.test(body.serverId) ? body.serverId : null);

/** POST /<packId>/conflicts { serverId, versionId? }: what installing would find on that server (nothing changes). */
export async function handleConflicts(packId: string, req: Request, d: ModPackApiDeps): Promise<Response> {
  const g = await gate(d);
  if (!g.ok) return g.res;
  const body = (await req.json().catch(() => null)) as Record<string, unknown> | null;
  const serverId = readServer(body);
  if (!serverId) return json(400, { error: "Pick a server.", code: "bad_server" });
  const t = await target(d, g.uid, packId, body?.versionId);
  if (t instanceof Response) return t;
  const s = await againstServer(d, g.uid, t, serverId);
  if (!s.ok) return s.res;
  return json(200, { packId, versionId: t.versionId, serverId, installable: s.blocking.length === 0, findings: s.view.findings, requiredAcks: [...s.required, "restart"], serverFindings: s.serverFindings, notes: s.view.notes });
}

async function enqueuePack(d: ModPackApiDeps, req: Request, uid: string, serverId: string, payload: Omit<DeliveryPayload, "key" | "v" | "requestedBy">, subject: string): Promise<Response> {
  const rawKey = req.headers.get("idempotency-key");
  if (rawKey !== null && !CLIENT_KEY_RE.test(rawKey)) return json(400, { error: "Idempotency-Key must be 8-128 letters, digits or _.:-", code: "bad_key" });
  const k = deliveryKey({ userId: uid, serverId, op: payload.op, subject, restartPolicy: payload.restartPolicy, clientKey: rawKey });
  const q = await d.enqueue({ userId: uid, serverId, payload: { ...payload, v: 1, key: k.key, requestedBy: uid }, keyKind: k.kind });
  if (!q.ok) return json(q.status, { error: q.error, code: q.code });
  const row = await d.job(uid, q.jobId);
  return json(q.reused ? 200 : 202, { jobId: q.jobId, reused: q.reused, status: row ? deliveryStatus(row) : null });
}

const readPolicy = (v: unknown): RestartPolicy | null => (v === undefined || v === "now" ? "now" : v === "next_restart" ? "next_restart" : null);

/** POST /<packId>/install { serverId, versionId?, acked, restartPolicy? } -> a delivery job (202). */
export async function handleInstall(packId: string, req: Request, d: ModPackApiDeps): Promise<Response> {
  const g = await gate(d, true);
  if (!g.ok) return g.res;
  const body = (await req.json().catch(() => null)) as Record<string, unknown> | null;
  const serverId = readServer(body);
  if (!serverId) return json(400, { error: "Pick a server.", code: "bad_server" });
  const policy = readPolicy(body?.restartPolicy);
  if (!policy) return json(400, { error: "restartPolicy must be now or next_restart.", code: "bad_policy" });
  const t = await target(d, g.uid, packId, body?.versionId);
  if (t instanceof Response) return t;
  const check = await d.checkServer({ userId: g.uid, serverId });
  if (!check.ok) return json(check.status, { error: check.error, code: check.code ?? "refused" });
  const s = await againstServer(d, g.uid, t, serverId);
  if (!s.ok) return s.res;
  if (s.blocking.length) return json(409, { error: "This pack conflicts with what the server already runs.", code: "blocking_conflicts", findings: s.blocking });
  const acked = readAcks(body?.acked);
  const required = [...s.required, ...(policy === "now" ? ["restart"] : [])];
  const missing = required.filter((id) => !acked.includes(id));
  if (missing.length) return json(409, { error: "Confirm every open warning first.", code: "needs_ack", acks: missing.map((id) => ({ id, text: id === "restart" ? ACK_TEXT.restart : s.view.findings.find((f) => f.id === id)?.message ?? "an open warning recorded in the pack" })) });
  return enqueuePack(d, req, g.uid, serverId, { op: "modpack_install", restartPolicy: policy, pack: { packId: t.meta.packId, versionId: t.versionId, sha256: t.sha256 }, acknowledge: acked }, `${t.meta.packId}@${t.versionId}`);
}

/** POST /<packId>/uninstall { serverId, acked, restartPolicy? } -> a delivery job (202). */
export async function handleUninstall(packId: string, req: Request, d: ModPackApiDeps): Promise<Response> {
  const g = await gate(d, true);
  if (!g.ok) return g.res;
  const body = (await req.json().catch(() => null)) as Record<string, unknown> | null;
  const serverId = readServer(body);
  if (!serverId) return json(400, { error: "Pick a server.", code: "bad_server" });
  const policy = readPolicy(body?.restartPolicy);
  if (!policy) return json(400, { error: "restartPolicy must be now or next_restart.", code: "bad_policy" });
  if (!STORE_PACK_ID_RE.test(packId) || !(await d.store.get(g.uid, packId))) return NOT_FOUND();
  const check = await d.checkServer({ userId: g.uid, serverId });
  if (!check.ok) return json(check.status, { error: check.error, code: check.code ?? "refused" });
  const acked = readAcks(body?.acked);
  if (policy === "now" && !acked.includes("restart")) return json(409, { error: "Confirm the restart first.", code: "needs_ack", acks: [{ id: "restart", text: ACK_TEXT.restart }] });
  return enqueuePack(d, req, g.uid, serverId, { op: "modpack_uninstall", restartPolicy: policy, packId, ...(acked.length ? { acknowledge: acked } : {}) }, packId);
}
