async function members(userId: string, buildId: string): Promise<MembersResult> {
  const b = await db.modBuild.findUnique({ where: { id: buildId } });
  if (!b || b.status !== "succeeded" || !b.jarPath) return { ok: false, status: 404, error: `Mod ${buildId} was not found or is not finished.` };
  if (b.userId !== userId) {
    const installed = await db.serverMod.findFirst({ where: { versionId: b.id, status: "INSTALLED", server: { userId, status: { notIn: ["DELETING"] } }, mod: { source: CYRUS_SOURCE } }, select: { id: true } });
    if (!installed) return { ok: false, status: 404, error: `Mod ${buildId} was not found or is not finished.` };
  }
  const root = b.rootBuildId ?? b.id;
  const proj = await db.cyrusProject.findUnique({ where: { rootBuildId: root }, select: { id: true, namespace: true } });
  const jar = await readFile(b.jarPath).catch(() => null);
  const revId = (b.result as { assets?: { revisionId?: string | null } } | null)?.assets?.revisionId ?? null;
  const rows = revId ? await db.cyrusProjectAsset.findMany({ where: { revisionId: revId, kind: "datapack" }, select: { assetKey: true, provenance: true } }) : [];
  const r = membersFromBuild(b, jar, proj, rows);
  return r.ok ? { ok: true, mcVersion: b.mcVersion, members: r.members, notes: r.notes } : { ok: false, status: 409, error: r.error };
}

async function inventory(userId: string, serverId: string, packId: string) {
  const s = await getHost().servers.openFiles(userId, serverId);
  if (!s) return null;
  try {
    const inv = await scanServer(s.fs, { base: s.base });
    const unit = await s.fs.readFile(`${cyrusConfig().guest.stateDir}/modpacks/${packId}.json`, 4 * 1024 * 1024).catch(() => null);
    let owned: string[] = [];
    try { owned = ((JSON.parse(unit?.toString("utf8") ?? "{}").files ?? []) as { path: string }[]).map((x) => x.path.slice(s.base.length + 1)); } catch { owned = []; }
    return { inventory: inv, ownedPaths: owned };
  } finally { s.close?.(); }
}

