// Cyrus Mod Packs (wiring phase 2): where a composed pack lives between "create" and "install". A small file store
// beside the built jars (NXEON_MODBUILD_DIR/modpacks/<userId>/<packId>/): pack.json (the definition + its versions)
// and one immutable <versionId>.zip per version (the builder's .nxpack archive). The web process writes it, the
// worker reads it (same host, same as ModBuild.jarPath) and re-verifies the archive's sha256 before it delivers.
// No table and no migration: the definition is small and per account; a database table can replace this later
// behind the same interface. Node fs only, no Nxeon import (host seam).
import { createHash, randomBytes } from "node:crypto";
import { mkdir, readFile, readdir, rename, writeFile } from "node:fs/promises";
import path from "node:path";
import { cyrusConfig } from "../config";
import { indexZip, readEntry } from "../inventory/zipread";
import { NXPACK_FILE, validateNxPack, type NxPack } from "./manifest";

export type PackMemberRef = { buildId: string };
export type PackVersionRow = { versionId: string; sha256: string; bytes: number; createdAt: string; openWarnings: string[]; blocking: number };
export type PackMeta = { schema: 1; packId: string; userId: string; name: string; summary?: string; mcVersion: string; members: PackMemberRef[]; versions: PackVersionRow[]; createdAt: string; updatedAt: string };

export interface ModPackStore {
  get(userId: string, packId: string): Promise<PackMeta | null>;
  list(userId: string): Promise<PackMeta[]>;
  /** Write the archive of a new version, then the definition (so a definition never names a missing archive). */
  save(meta: PackMeta, version?: { versionId: string; zip: Buffer }): Promise<void>;
  readVersion(userId: string, packId: string, versionId: string): Promise<Buffer | null>;
}

const USER_RE = /^[A-Za-z0-9_-]{1,64}$/;
export const STORE_PACK_ID_RE = /^mp_[a-z0-9]{12}$/;
const VERSION_RE = /^\d{1,6}\.\d{1,6}\.\d{1,6}$/;
export const newPackId = () => `mp_${[...randomBytes(12)].map((b) => "abcdefghijklmnopqrstuvwxyz0123456789"[b % 36]).join("")}`;
export const sha256Hex = (b: Buffer) => createHash("sha256").update(b).digest("hex");

export class FsModPackStore implements ModPackStore {
  constructor(readonly root = path.join(cyrusConfig().modbuildDir, "modpacks")) {}
  private dir(userId: string, packId: string) {
    if (!USER_RE.test(userId) || !STORE_PACK_ID_RE.test(packId)) throw new Error("bad pack path");
    return path.join(this.root, userId, packId);
  }
  async get(userId: string, packId: string): Promise<PackMeta | null> {
    let raw: string;
    try { raw = await readFile(path.join(this.dir(userId, packId), "pack.json"), "utf8"); } catch { return null; }
    try { const m = JSON.parse(raw) as PackMeta; return m.schema === 1 && m.packId === packId && m.userId === userId ? m : null; } catch { return null; }
  }
  async list(userId: string): Promise<PackMeta[]> {
    if (!USER_RE.test(userId)) return [];
    let ids: string[] = [];
    try { ids = (await readdir(path.join(this.root, userId))).filter((n) => STORE_PACK_ID_RE.test(n)); } catch { return []; }
    const out = (await Promise.all(ids.map((id) => this.get(userId, id)))).filter((m): m is PackMeta => !!m);
    return out.sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : -1));
  }
  async save(meta: PackMeta, version?: { versionId: string; zip: Buffer }): Promise<void> {
    const d = this.dir(meta.userId, meta.packId);
    await mkdir(d, { recursive: true, mode: 0o750 });
    const atomic = async (name: string, data: Buffer | string) => { const t = path.join(d, `.${name}.${process.pid}.part`); await writeFile(t, data, { mode: 0o640 }); await rename(t, path.join(d, name)); };
    if (version) {
      if (!VERSION_RE.test(version.versionId)) throw new Error("bad version id");
      await atomic(`${version.versionId}.zip`, version.zip);
    }
    await atomic("pack.json", JSON.stringify(meta, null, 1));
  }
  async readVersion(userId: string, packId: string, versionId: string): Promise<Buffer | null> {
    if (!VERSION_RE.test(versionId)) return null;
    try { return await readFile(path.join(this.dir(userId, packId), `${versionId}.zip`)); } catch { return null; }
  }
}

/** An in-memory store (tests, previews). */
export class MemoryModPackStore implements ModPackStore {
  metas = new Map<string, PackMeta>();
  zips = new Map<string, Buffer>();
  async get(userId: string, packId: string) { const m = this.metas.get(`${userId}/${packId}`); return m ? (JSON.parse(JSON.stringify(m)) as PackMeta) : null; }
  async list(userId: string) { return [...this.metas.values()].filter((m) => m.userId === userId).map((m) => JSON.parse(JSON.stringify(m)) as PackMeta); }
  async save(meta: PackMeta, version?: { versionId: string; zip: Buffer }) { if (version) this.zips.set(`${meta.userId}/${meta.packId}/${version.versionId}`, version.zip); this.metas.set(`${meta.userId}/${meta.packId}`, JSON.parse(JSON.stringify(meta))); }
  async readVersion(userId: string, packId: string, versionId: string) { return this.zips.get(`${userId}/${packId}/${versionId}`) ?? null; }
}

/** A stored archive -> the manifest + archive map the orchestrator takes, verified (sha256, manifest schema, pack id). */
export function openPackArchive(zip: Buffer, expect: { sha256: string; packId: string; versionId: string }): { ok: true; manifest: NxPack; archive: Map<string, Buffer> } | { ok: false; error: string } {
  if (sha256Hex(zip) !== expect.sha256) return { ok: false, error: "the stored Mod Pack does not match its recorded sha256" };
  const z = indexZip(zip);
  if (!z.ok) return { ok: false, error: `the stored Mod Pack is not a valid archive: ${z.error}` };
  if (z.zip.unsafeNames.length) return { ok: false, error: "the stored Mod Pack has unsafe entry names" };
  const archive = new Map<string, Buffer>();
  for (const e of z.zip.entries) {
    if (e.dir) continue;
    const r = readEntry(z.zip, e);
    if (!r.ok) return { ok: false, error: `${e.name}: ${r.error}` };
    archive.set(e.name, r.data);
  }
  const raw = archive.get(NXPACK_FILE);
  if (!raw) return { ok: false, error: `the stored Mod Pack has no ${NXPACK_FILE}` };
  let j: unknown;
  try { j = JSON.parse(raw.toString("utf8")); } catch { return { ok: false, error: `${NXPACK_FILE} is not JSON` }; }
  const v = validateNxPack(j);
  if (!v.ok) return { ok: false, error: `invalid ${NXPACK_FILE}: ${v.errors[0]?.message ?? "?"}` };
  if (v.pack.packId !== expect.packId || v.pack.versionId !== expect.versionId) return { ok: false, error: "the stored Mod Pack is not the version that was requested" };
  return { ok: true, manifest: v.pack, archive };
}

