// Cyrus data pack studio: the SAFETY validator for .mcfunction files (pure, deterministic, no game parsing).
//
// Why it exists: data pack functions run as the server (permission level `function-permission-level`, 2 by default and
// up to 4 on some hosts), from #minecraft:load / #minecraft:tick, without any player. A generated function must never
// be able to take over or break a customer's server. So every command is checked against an ALLOWLIST of command
// roots (everything else is refused, including plugin commands such as /lp), `execute ... run <cmd>` chains are
// unwrapped and checked to the end, the call graph (function, schedule, execute if function, function tags) must be
// acyclic and shallow, and size / loop limits apply. Fail closed: anything the checker cannot read is refused.
//
// Each finding is { severity: "error" | "warn", rule, at, message }. Errors block the pack, warnings are shown.

export const FN_LIMITS = {
  maxFunctions: 64,
