  maxCommandsTotal: 2048,
  maxLineLength: 2000,
  maxBytesTotal: 256 * 1024,
  /** Longest call chain (A calls B calls C ... ), counted in functions. */
  maxCallDepth: 8,
  /** Commands in a function that runs every tick (and everything it calls). */
  maxTickCommands: 64,
