// Cyrus Config Studio: the HTTP handler of /api/cyrus/config/v1 (framework-free Request -> Response, tested with
// fakes; app/api/cyrus/config/v1/route.ts is a one-line wrapper with configApiDeps()). Gates in order: the studios
// viewer (anyone else: 404 as if the route did not exist) -> CYRUS_CONFIG_STUDIO (off: 404) -> rate limit -> input
// validation -> the service (ownership on the project, fail closed). NOT plan-gated: editing numbers is not asset
// creation (owner decision pending; proposed ungated).
//   GET  ?root=<rootBuildId>                                   the settings view
//   POST { root, action: "preview", values }                    what a save would write (config.yml + diff), no write
//   POST { root, action: "save", values, expectedHeadId, message? }
//   POST { root, action: "revert", revisionId, expectedHeadId }  undo one settings revision (a new revision)
//   POST { root, action: "plan", text }                          "set walk speed to 0.3" -> edits, no model call
//   POST { root, action: "deliver", serverId }                   send the settings to a server (host wiring needed)
import { ConfigError, configView, deliverConfigValues, planConfig, previewConfig, revertConfig, saveConfigValues, type ConfigServiceDeps } from "./service";

export type ConfigViewer = { userId: string; preview: boolean };
export type ConfigApiDeps = {
  viewer: () => Promise<ConfigViewer | null>;
  flagOn: () => boolean | Promise<boolean>;
  service: ConfigServiceDeps;
  rateLimit: (key: string, max: number, windowMs: number) => { ok: boolean; retryAfterSec?: number };
};

const H = { "cache-control": "no-store", "x-robots-tag": "noindex" };
const json = (status: number, body: unknown) => Response.json(body, { status, headers: H });
const NOT_FOUND = () => json(404, { error: "Not found" });
const ROOT_RE = /^[A-Za-z0-9_-]{1,64}$/;
const ID_RE = /^[A-Za-z0-9_-]{1,64}$/;
const MAX_BODY = 256 * 1024;

async function body(req: Request): Promise<Record<string, unknown>> {
  if (Number(req.headers.get("content-length") ?? 0) > MAX_BODY) throw new ConfigError(413, "too_large", "That request is too large.");
  const t = await req.text();
  if (t.length > MAX_BODY) throw new ConfigError(413, "too_large", "That request is too large.");
  try { const v = JSON.parse(t || "{}"); if (v && typeof v === "object" && !Array.isArray(v)) return v; } catch { /* below */ }
  throw new ConfigError(400, "bad_json", "Send a JSON object.");
}
const valuesOf = (v: unknown): Record<string, unknown> => {
  if (!v || typeof v !== "object" || Array.isArray(v)) throw new ConfigError(400, "bad_values", "values must be an object of setting keys.");
  if (Object.keys(v).length > 400) throw new ConfigError(400, "bad_values", "Too many settings in one request.");
  return v as Record<string, unknown>;
};

export async function handleConfig(req: Request, deps: ConfigApiDeps): Promise<Response> {
  try {
    const viewer = await deps.viewer().catch(() => null);
    if (!viewer) return NOT_FOUND();
    if (!(await Promise.resolve(deps.flagOn()).catch(() => false))) return NOT_FOUND();
    const write = req.method === "POST";
    const rl = deps.rateLimit(`config:${write ? "w" : "r"}:${viewer.userId}`, write ? 60 : 240, 60_000);
    if (!rl.ok) return json(429, { error: "Too many requests. Try again in a moment.", retryAfterSec: rl.retryAfterSec ?? 60 });
    if (req.method === "GET") {
      const root = new URL(req.url).searchParams.get("root") ?? "";
      if (!ROOT_RE.test(root)) return json(400, { error: "root must be a build id" });
      return json(200, await configView(deps.service, viewer.userId, root));
    }
    if (!write) return json(405, { error: "Method not allowed" });
    const b = await body(req);
    const root = String(b.root ?? "");
    if (!ROOT_RE.test(root)) return json(400, { error: "root must be a build id" });
    const head = b.expectedHeadId === null || b.expectedHeadId === undefined ? null : String(b.expectedHeadId);
    if (head !== null && !ID_RE.test(head)) return json(400, { error: "bad expectedHeadId" });
    switch (b.action) {
      case "preview": return json(200, await previewConfig(deps.service, viewer.userId, root, valuesOf(b.values)));
      case "save": return json(201, await saveConfigValues(deps.service, { userId: viewer.userId, rootBuildId: root, values: valuesOf(b.values), expectedHeadId: head, message: typeof b.message === "string" ? b.message.slice(0, 200) : undefined }));
      case "revert": {
        const id = String(b.revisionId ?? "");
        if (!ID_RE.test(id)) return json(400, { error: "bad revisionId" });
        return json(201, await revertConfig(deps.service, { userId: viewer.userId, rootBuildId: root, revisionId: id, expectedHeadId: head }));
      }
      case "plan": {
        const text = typeof b.text === "string" ? b.text : "";
        if (!text || text.length > 400) return json(400, { error: "text must be 1-400 characters" });
        return json(200, await planConfig(deps.service, viewer.userId, root, text));
      }
      case "deliver": {
        const sid = String(b.serverId ?? "");
        if (!ID_RE.test(sid)) return json(400, { error: "bad serverId" });
        return json(200, await deliverConfigValues(deps.service, { userId: viewer.userId, rootBuildId: root, serverId: sid }));
      }
      default: return json(400, { error: "action must be preview, save, revert, plan or deliver" });
    }
  } catch (e) {
    if (e instanceof ConfigError) return json(e.status, { error: e.message, code: e.code, ...e.extra });
    const code = (e as { code?: string }).code;
    if (code === "stale_head") return json(409, { error: "This mod changed since you opened it. Reload to see the newest settings.", code });
    console.error("[cyrus-config] request failed:", (e as Error).message);
    return json(500, { error: "Something went wrong." });
  }
}

