export const CYRUS_STUDIOS_FLAG = "cyrus_studios_enabled";

/** The studios setting. Fails CLOSED: a settings/DB error never opens them. */
export async function studiosFlagOn(): Promise<boolean> {
  try { return await getHost().settings.getBool(CYRUS_STUDIOS_FLAG, false); } catch { return false; }
}

/** Who may see the studios now: a Cyrus user (preview or public launch) AND (preview OR the setting is on). */
export async function studioViewer(): Promise<(StudioViewer & { user: User }) | null> {
  const user = await modBuilderUser().catch(() => null);
  if (!user) return null;
  const [previewUser, flagOn] = await Promise.all([getHost().access.isPreviewUser(user, "modbuilder").catch(() => false), studiosFlagOn()]);
  return studiosOpen({ cyrusUser: true, previewUser, flagOn }) ? { userId: user.id, user, preview: previewUser } : null;
}

/**
 * The plan lookup (host seam: tokens tierOf). Non-production only: CYRUS_STUDIO_TEST_PLAN_UNKNOWN=<userId,...> makes
 * the lookup fail for those accounts, so the fail-closed "plan unknown" state can be exercised on devhost.
 */
export function studioPlanOf(env: Record<string, string | undefined> = process.env) {
  const faulty = env.NODE_ENV !== "production" ? new Set((env.CYRUS_STUDIO_TEST_PLAN_UNKNOWN ?? "").split(",").filter(Boolean)) : new Set<string>();
  return async (userId: string): Promise<unknown> => { if (faulty.has(userId)) throw new Error("plan lookup failed (test fault)"); return tierOf(userId); };
}

export function serviceDeps(env: Record<string, string | undefined> = process.env): StudioServiceDeps {
  return {
    store: prismaStudioStore,
    planOf: studioPlanOf(env),
    chain: chainOf,
    deliveryOn: () => env[MANAGED_REAL_FLAG] === "1",
    contribute: studioContributor(env),
    publish: async (zip) => {
      const sel = selectPackStore(env);
      if (!sel.ok) return { ok: false, reason: sel.reason };
      const r = await publishPack(sel.store, zip, { maxBytes: sel.maxBytes });
      return r.ok ? { ok: true, url: r.url, sha1: r.sha1 } : { ok: false, reason: r.error };
    },
  };
}

