// Cyrus designer studio UI: the HTTP handlers of /api/cyrus/designer/v1/** (framework-free Request -> Response, tested
// with fakes; app/api/cyrus/designer/v1/** are one-line wrappers with designerApiDeps()). Every handler: viewer (a Cyrus
// user who may see the studios AND the designer switch CYRUS_DESIGNER is on; anyone else gets a 404 as if the route
// did not exist) -> rate limit -> input validation -> ownership (the service) -> the service. Designers are not
// plan-gated; nothing here writes outside Cyrus tables and nothing calls a model.
import { StudioError } from "../../studios/service";
import { json, NOT_FOUND, readJson, RE, type StudioViewer } from "../../studios/http";
import { buildRevision, checkDesigns, designerView, dropDraft, planEdit, putDraft, saveDesigns, simulate, type DesignerDeps } from "./service";
import type { BossStep, ItemStep, QuestStep } from "./sim";

export type DesignerApiDeps = {
  viewer: () => Promise<StudioViewer | null>;
  service: DesignerDeps;
  rateLimit: (key: string, max: number, windowMs: number) => { ok: boolean; retryAfterSec?: number };
};

async function run(deps: DesignerApiDeps, limit: { key: string; max: number }, body: (v: StudioViewer) => Promise<Response>): Promise<Response> {
  const viewer = await deps.viewer().catch(() => null);
  if (!viewer) return NOT_FOUND();
  const rl = deps.rateLimit(`designer:${limit.key}:${viewer.userId}`, limit.max, 60_000);
  if (!rl.ok) return json(429, { error: `Too many requests. Wait ${rl.retryAfterSec ?? 30}s.`, code: "rate_limited" });
  try {
    return await body(viewer);
  } catch (e) {
    if (e instanceof StudioError) return json(e.status, { error: e.message, code: e.code, ...e.extra });
    console.error("[cyrus-designer]", limit.key, (e as Error).message);
    return json(500, { error: "Something went wrong on our side. Nothing was changed.", code: "server_error" });
  }
}
const need = (ok: boolean, msg: string) => { if (!ok) throw new StudioError(400, "bad_request", msg); };
const pid = (p: { projectId?: string }) => { need(RE.project.test(p.projectId ?? ""), "projectId is not valid"); return p.projectId!; };
const headId = (v: unknown) => { need(v === null || (typeof v === "string" && RE.id.test(v)), "expectedHeadId must be a revision id or null"); return v as string | null; };

const STEP_KINDS = new Set(["hit", "kill", "click", "sneak_click", "charge", "wait", "consume", "projectile", "join", "die"]);
const Q_KINDS = new Set(["start", "kill", "break", "pickup", "craft", "visit", "talk", "survive", "choose", "day", "die"]);
const id = /^[a-z][a-z0-9_]{1,31}$/, vref = /^minecraft:[a-z0-9_./]+$/;
function itemSteps(raw: unknown): ItemStep[] {
  need(Array.isArray(raw) && raw.length <= 40, "steps must be a list (at most 40)");
  return (raw as unknown[]).map((s) => {
    const o = (s ?? {}) as Record<string, unknown>;
    need(typeof o.k === "string" && STEP_KINDS.has(o.k), "unknown simulator step");
    if (o.k === "hit") need(o.who === "hostile" || o.who === "animal", "hit needs who");
    if (o.k === "charge" || o.k === "wait") need(typeof o.ticks === "number" && Number.isFinite(o.ticks) && o.ticks > 0 && o.ticks <= 2400, "ticks must be 1-2400");
    return o as ItemStep;
  });
}
function questSteps(raw: unknown): QuestStep[] {
  need(Array.isArray(raw) && raw.length <= 40, "steps must be a list (at most 40)");
  return (raw as unknown[]).map((s) => {
    const o = (s ?? {}) as Record<string, unknown>;
    need(typeof o.k === "string" && Q_KINDS.has(o.k), "unknown simulator step");
    for (const f of ["quest", "branch", "menu"]) if (o[f] !== undefined) need(typeof o[f] === "string" && id.test(o[f] as string), `${f} is not valid`);
    for (const f of ["entity", "block", "item"]) if (o[f] !== undefined) need(typeof o[f] === "string" && (vref.test(o[f] as string) || id.test(o[f] as string)), `${f} is not valid`);
    for (const f of ["count", "seconds"]) if (o[f] !== undefined) need(typeof o[f] === "number" && Number.isFinite(o[f] as number) && (o[f] as number) >= 0 && (o[f] as number) <= 7200, `${f} is out of range`);
    if (o.k === "visit") need(Array.isArray(o.pos) && o.pos.length === 3 && (o.pos as unknown[]).every((n) => typeof n === "number" && Math.abs(n) <= 3e7) && typeof o.world === "string" && /^[A-Za-z0-9_./-]{1,64}$/.test(o.world), "visit needs world and pos");
    if (o.kinds !== undefined) need(Array.isArray(o.kinds) && (o.kinds as unknown[]).every((k) => typeof k === "string" && /^[a-z]{1,12}$/.test(k)), "kinds is not valid");
    return o as QuestStep;
  });
}

