/** POST .../projects/:projectId/simulate { files, mode: item|menu|quests, ... }: the reference simulators (logic only). */
export const handleSimulate = (req: Request, p: { projectId?: string }, deps: DesignerApiDeps) => run(deps, { key: "sim", max: 240 }, async (v) => {
  const b = await readJson(req);
  if (b.mode === "item") { need(typeof b.item === "string" && id.test(b.item), "item is not valid"); return json(200, await simulate(deps.service, v.userId, pid(p), { files: b.files, mode: "item", item: b.item as string, steps: itemSteps(b.steps) })); }
  if (b.mode === "menu") {
    need(typeof b.menu === "string" && id.test(b.menu), "menu is not valid");
    need(Array.isArray(b.clicks) && b.clicks.length <= 40 && (b.clicks as unknown[]).every((s) => Number.isInteger(s) && (s as number) >= 0 && (s as number) < 54), "clicks must be slot numbers 0-53");
    return json(200, await simulate(deps.service, v.userId, pid(p), { files: b.files, mode: "menu", menu: b.menu as string, clicks: b.clicks as number[] }));
  }
  if (b.mode === "boss") {
    need(typeof b.boss === "string" && id.test(b.boss), "boss is not valid");
    need(Array.isArray(b.steps) && b.steps.length <= 40, "steps must be a list (at most 40)");
    const steps = (b.steps as Record<string, unknown>[]).map((s) => {
      need(!!s && typeof s === "object" && ["hit", "wait", "join", "leave"].includes(String(s.k)), "unknown simulator step");
      if (s.k === "hit") need(typeof s.pct === "number" && s.pct > 0 && s.pct <= 100, "pct must be 1-100");
      if (s.k === "wait") need(typeof s.seconds === "number" && s.seconds > 0 && s.seconds <= 600, "seconds must be 1-600");
      return s as BossStep;
    });
    return json(200, await simulate(deps.service, v.userId, pid(p), { files: b.files, mode: "boss", boss: b.boss as string, steps }));
  }
  if (b.mode === "quests") return json(200, await simulate(deps.service, v.userId, pid(p), { files: b.files, mode: "quests", steps: questSteps(b.steps) }));
  throw new StudioError(400, "bad_request", "mode must be item, menu, quests or boss");
});

