// Cyrus r31: the HOST side of shipping a Designer Studio revision (lib/cyrus/designer/studio/service.ts ShipDeps). Nxeon
// code (the ModBuild table, the account's servers), so it lives outside lib/cyrus and is injected by the designer routes.
// Switches: CYRUS_DESIGNER_BUILDS=1 (default off) shows "Build this revision"; delivery is the existing enqueue API
// (/api/cyrus/delivery/v1, CYRUS_DELIVERY=1 + its own worker switches), which re-checks everything on every call.
import { db } from "@/lib/db";
import { readCyrusMeta } from "@/lib/cyrus/meta";
import { deliveryEnabled } from "@/lib/cyrus/delivery/api";
import { createDesignerBuild } from "@/lib/modbuilder/create";
import { modBuilderServers } from "@/lib/modbuilder/install";
import type { ShipDeps } from "@/lib/cyrus/designer/studio/service";

export const designerBuildsOn = (env: Record<string, string | undefined> = process.env) => env.CYRUS_DESIGNER_BUILDS === "1";

export function designerShipDeps(env: Record<string, string | undefined> = process.env): ShipDeps {
  return {
    buildsOn: () => designerBuildsOn(env),
    deliveryOn: () => deliveryEnabled(env),
    async start(userId, input) {
      const user = await db.user.findUnique({ where: { id: userId } });
      if (!user) return { ok: false, status: 404, error: "Not found" };
      const r = await createDesignerBuild(user, input);
      return r.ok ? { ok: true, buildId: r.build.id } : { ok: false, status: r.status, error: String(r.json.error ?? "The build was refused."), code: typeof r.json.code === "string" ? r.json.code : undefined };
    },
    async latest(userId, rootBuildId) {
      const rows = await db.modBuild.findMany({ where: { userId, OR: [{ id: rootBuildId }, { rootBuildId }], changeRequest: { startsWith: "Designer edit" } }, orderBy: { createdAt: "desc" }, take: 5, select: { id: true, status: true, error: true, cyrus: true, 
      for (const r of rows) {
        const d = readCyrusMeta(r.cyrus).designer;
        if (d) return { id: r.id, status: r.status, error: r.error, revisionId: d.revisionId, seq: d.seq, configOnly: d.configOnly, createdAt: r.createdAt.toISOString() };
      }
      return null;
    },
    async servers(userId) {
      return (await modBuilderServers(userId)).map((s) => ({ id: s.id, name: s.name, compatible: s.compatible, ...(s.reason ? { reason: s.reason } : {}) }));
    },
  };
}
