const json = (status: number, body: unknown) => new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store", "x-robots-tag": "noindex" } });
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
const ROOT_RE = /^[A-Za-z0-9_-]{1,64}$/;
const WORLDGEN_TYPES = new Set(["dimension_type", "dimension", "biome", "configured_feature", "placed_feature", "structure", "structure_set", "structure_template", "noise_settings", "configured_carver"]);
export const hasWorldgenSpec = (spec: unknown) => (Array.isArray(obj(spec).resources) ? (obj(spec).resources as unknown[]) : []).some((r) => WORLDGEN_TYPES.has(String(obj(r).type)));

/** Pure: one pack's report across versions (validate + emit per version). */
export function packView(row: AssetRow, namespace: string, worldgenOn: boolean): PackView | null {
  const spec = obj(row.provenance).spec;
  if (!spec) return null;
  const s = obj(spec);
  const resources = (Array.isArray(s.resources) ? (s.resources as unknown[]) : []).slice(0, 400).map((r) => ({ type: String(obj(r).type ?? "?"), id: String(obj(r).id ?? "?"), json: r }));
  const worldgen = hasWorldgenSpec(spec);
  const versions = DATAPACK_VERSIONS.map((version): PackVersion => {
    const ctx = { version, namespace, worldgen: worldgen && worldgenOn };
    const v = validateDataPackSpec(spec, ctx);
    if (!v.ok) return { version, ok: false, apply: null, worldgen, files: 0, errors: v.errors.slice(0, 6).map((e) => `${e.path}: ${e.message}`), warnings: v.warnings.slice(0, 6).map((w) => `${w.path}: ${w.message}`), checks: v.checks };
    const b = buildDataPack(spec, ctx);
    if (!b.ok) return { version, ok: false, apply: null, worldgen, files: 0, errors: b.errors.slice(0, 6), warnings: [], checks: b.checks };
    return { version, ok: true, apply: b.pack.apply, worldgen: !!b.pack.worldgen, files: b.pack.files.length, errors: [], warnings: v.warnings.slice(0, 6).map((w) => `${w.path}: ${w.message}`), checks: v.checks };
  });
  return { name: row.assetKey, description: typeof s.description === "string" ? s.description.slice(0, 300) : null, assetId: row.id, createdAt: new Date(row.createdAt).toISOString(), worldgen, resources, versions };
}

export async function datapackStudioView(deps: DatapackViewDeps, userId: string, root: string): Promise<DatapackStudioView | null> {
  const chain = await deps.chain(userId, root);
  if (!chain) return null;
  const p = await deps.store.projectForRoot(chain.rootBuildId);
  const buildIds = await deps.buildIds(userId, chain.rootBuildId).catch(() => []);
  if (!p || p.userId !== userId) return { mcVersion: chain.mcVersion, namespace: null, projectId: null, worldgenOn: deps.worldgenOn(), packs: [], buildIds };
  const rows = (await deps.store.assets(p.id)).filter((r) => r.kind === "datapack" && obj(r.provenance).spec);
  const newest = new Map<string, AssetRow>();
  for (const r of rows) { const cur = newest.get(r.assetKey); if (!cur || new Date(r.createdAt).getTime() > new Date(cur.createdAt).getTime()) newest.set(r.assetKey, r); }
  const packs = [...newest.values()].sort((a, b) => (a.assetKey < b.assetKey ? -1 : 1)).slice(0, 16).map((r) => packView(r, p.namespace, deps.worldgenOn())).filter((x): x is PackView => !!x);
  return { mcVersion: chain.mcVersion, namespace: p.namespace, projectId: p.id, worldgenOn: deps.worldgenOn(), packs, buildIds };
}

/** GET /api/cyrus/datapacks/v1?root=<rootBuildId> */
export async function handleDatapackView(req: Request, deps: DatapackViewDeps): Promise<Response> {
  if (!deps.on()) return json(404, { error: "Not found" });
  const v = await deps.viewer().catch(() => null);
  if (!v) return json(404, { error: "Not found" });
  const rl = deps.rateLimit(`datapacks:read:${v.userId}`, 60, 60_000);
  if (!rl.ok) return json(429, { error: `Too many requests. Wait ${rl.retryAfterSec ?? 30}s.`, code: "rate_limited" });
  const root = new URL(req.url).searchParams.get("root") ?? "";
  if (!ROOT_RE.test(root)) return json(400, { error: "root must be a build id", code: "bad_request" });
  try {
    const view = await datapackStudioView(deps, v.userId, root);
    return view ? json(200, view) : json(404, { error: "Not found" });
  } catch (e) {
    console.error("[cyrus-datapacks]", (e as Error).message);
    return json(500, { error: "Something went wrong on our side.", code: "server_error" });
  }
}

